INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('99e73932-c99d-510c-ace8-1e4f43f0e06a', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 1, 1, 'Praise waits for you, God, in Zion. To you shall vows be performed.'),
  ('fc581f86-c698-5eed-a651-516cdb30e511', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 2, 2, 'You who hear prayer, to you all men will come.'),
  ('e07787c5-aa92-5709-a260-412ecba2f6e2', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 3, 3, 'Sins overwhelmed me, but you atoned for our transgressions.'),
  ('105e33e7-efb6-5368-a167-42d98be96785', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 4, 4, 'Blessed is one whom you choose, and cause to come near, that he may live in your courts. We will be filled with the goodness of your house, your holy temple.'),
  ('ecb13152-4ffc-53dd-ab6e-a27aeadff8db', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 5, 5, 'By awesome deeds of righteousness, you answer us, God of our salvation. You who are the hope of all the ends of the earth, of those who are far away on the sea;'),
  ('540a0bf6-19c4-5c27-a010-f3990509d0c8', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 6, 6, 'Who by his power forms the mountains, having armed yourself with strength;'),
  ('29420d42-abeb-5677-a9b0-a95ed9a37c6c', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 7, 7, 'who stills the roaring of the seas, the roaring of their waves, and the turmoil of the nations.'),
  ('efc55906-2202-5fd9-acbc-680e23179d56', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 8, 8, 'They also who dwell in faraway places are afraid at your wonders. You call the morning''s dawn and the evening with songs of joy.'),
  ('106c741d-dca0-5a96-ac97-4c128a7c524c', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 9, 9, 'You visit the earth, and water it. You greatly enrich it. The river of God is full of water. You provide them grain, for so you have ordained it.'),
  ('d179e667-308e-5049-a90b-752e4d1e3b6a', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 10, 10, 'You drench its furrows. You level its ridges. You soften it with showers. You bless it with a crop.'),
  ('4488b342-2706-5346-af76-18cc1f896981', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 11, 11, 'You crown the year with your bounty. Your carts overflow with abundance.'),
  ('5088558f-0f86-5f84-a462-2d0e4bd45d7b', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 12, 12, 'The wilderness grasslands overflow. The hills are clothed with gladness.'),
  ('3d9c3e10-3363-5c24-ade8-5ad054022754', '8fb64539-cfa1-5911-af1a-5d8c6c73e036', NULL, 13, 13, 'The pastures are covered with flocks. The valleys also are clothed with grain. They shout for joy! They also sing. For the Chief Musician. A song. A Psalm.'),
  ('603cc281-baf3-5300-a741-6f7e1651be7d', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 1, 1, 'Make a joyful shout to God, all the earth!'),
  ('772a2314-88d9-5b4b-a192-d87e1a0fe995', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 2, 2, 'Sing to the glory of his name! Offer glory and praise!'),
  ('72bc3d8f-ec5b-5ec7-a73e-edca0fb15542', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 3, 3, 'Tell God, "How awesome are your deeds! Through the greatness of your power, your enemies submit themselves to you.'),
  ('1b10bee0-5a68-5ae0-adce-3e650a3c97c7', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 4, 4, 'All the earth will worship you, and will sing to you; they will sing to your name." Selah.'),
  ('326eca8a-729e-53dd-aca4-29d359397b93', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 5, 5, 'Come, and see God''s deeds-- awesome work on behalf of the children of men.'),
  ('39b48ffe-a8e1-51d7-a48a-e0412aaeb633', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 6, 6, 'He turned the sea into dry land. They went through the river on foot. There, we rejoiced in him.'),
  ('fb39dffa-f143-5ede-af70-50ff64904ac0', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 7, 7, 'He rules by his might forever. His eyes watch the nations. Don''t let the rebellious rise up against him. Selah.'),
  ('4a19936d-a37c-53e6-ad39-28ae0d7f769f', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 8, 8, 'Praise our God, you peoples! Make the sound of his praise heard,'),
  ('d84226d0-749a-5618-afe2-980a34ab0110', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 9, 9, 'who preserves our life among the living, and doesn''t allow our feet to be moved.'),
  ('19edf6c1-d42b-5b84-a019-eb843030ef71', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 10, 10, 'For you, God, have tested us. You have refined us, as silver is refined.'),
  ('7d63b27d-e067-561a-ac8d-cb6d766af788', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 11, 11, 'You brought us into prison. You laid a burden on our backs.'),
  ('bab3f198-afb9-5358-aba6-118e5e17c9b1', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 12, 12, 'You allowed men to ride over our heads. We went through fire and through water, but you brought us to the place of abundance.'),
  ('b0f35fb5-41ae-51b7-a706-3d1179fe4e83', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 13, 13, 'I will come into your temple with burnt offerings. I will pay my vows to you,'),
  ('8ef37baa-ab9f-5ac9-a3f0-de8456c518f3', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 14, 14, 'which my lips promised, and my mouth spoke, when I was in distress.'),
  ('77b13597-e2b9-5fdb-a9ac-9c5f45167b49', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 15, 15, 'I will offer to you burnt offerings of fat animals, with the offering of rams, I will offer bulls with goats. Selah.'),
  ('0c4c7bf9-1a32-5bdc-aacd-ede6a879f676', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 16, 16, 'Come, and hear, all you who fear God. I will declare what he has done for my soul.'),
  ('f089bb09-ed23-5f6d-ad9a-9ab68196bed8', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 17, 17, 'I cried to him with my mouth. He was extolled with my tongue.'),
  ('2038b4df-715b-52f0-afaa-075ed3579029', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 18, 18, 'If I cherished sin in my heart, the Lord wouldn''t have listened.'),
  ('30969d8f-1a84-5e56-aae2-c494bc993a48', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 19, 19, 'But most certainly, God has listened. He has heard the voice of my prayer.'),
  ('81711cf6-db64-5972-acfe-fd330da3f730', '5dc8608c-3a2b-5615-aeac-a93861cc015e', NULL, 20, 20, 'Blessed be God, who has not turned away my prayer, nor his loving kindness from me. For the Chief Musician. With stringed instruments. A Psalm. A song.'),
  ('c3008cee-7055-5a85-af1e-ac852dc4e2d4', 'd8548340-0324-5adf-a486-1d1fb2b1029c', NULL, 1, 1, 'May God be merciful to us, bless us, and cause his face to shine on us. Selah.'),
  ('ab43ea7e-0147-5b9d-ae4f-5f6a2bcd4e53', 'd8548340-0324-5adf-a486-1d1fb2b1029c', NULL, 2, 2, 'That your way may be known on earth, and your salvation among all nations,'),
  ('f1bc7db5-496d-5110-a905-476e713981e9', 'd8548340-0324-5adf-a486-1d1fb2b1029c', NULL, 3, 3, 'let the peoples praise you, God. Let all the peoples praise you.'),
  ('ebeba9ca-b7cb-557a-ac5c-1048ecc78ca2', 'd8548340-0324-5adf-a486-1d1fb2b1029c', NULL, 4, 4, 'Oh let the nations be glad and sing for joy, for you will judge the peoples with equity, and govern the nations on earth. Selah.'),
  ('212609b2-b537-536a-ab19-8fef5e371ac9', 'd8548340-0324-5adf-a486-1d1fb2b1029c', NULL, 5, 5, 'Let the peoples praise you, God. Let all the peoples praise you.'),
  ('e65720c1-17c0-54f7-aa92-122540afa8c8', 'd8548340-0324-5adf-a486-1d1fb2b1029c', NULL, 6, 6, 'The earth has yielded its increase. God, even our own God, will bless us.'),
  ('e500576c-30bc-551e-ad27-3bd75de14250', 'd8548340-0324-5adf-a486-1d1fb2b1029c', NULL, 7, 7, 'God will bless us. All the ends of the earth shall fear him. For the Chief Musician. A Psalm by David. A song.'),
  ('dfa8f712-a85e-523b-a788-eed65325d57e', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 1, 1, 'Let God arise! Let his enemies be scattered! Let them who hate him also flee before him.'),
  ('f0923657-168d-5240-ae88-e51f4e0fa4a9', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 2, 2, 'As smoke is driven away, so drive them away. As wax melts before the fire, so let the wicked perish at the presence of God.'),
  ('4e31effd-f20f-5fb3-a4a2-d52ad9fbc815', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 3, 3, 'But let the righteous be glad. Let them rejoice before God. Yes, let them rejoice with gladness.'),
  ('a662870d-5937-55fa-a85e-d4e8018525e3', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 4, 4, 'Sing to God! Sing praises to his name! Extol him who rides on the clouds: to Yah, his name! Rejoice before him!'),
  ('b2882f6b-16e8-52a9-aba7-210a6b13c3e1', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 5, 5, 'A father of the fatherless, and a defender of the widows, is God in his holy habitation.'),
  ('feebbab5-2bb2-5755-a8a3-c0fcc117c194', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 6, 6, 'God sets the lonely in families. He brings out the prisoners with singing, but the rebellious dwell in a sun-scorched land.'),
  ('96013515-0cdf-5440-afb7-999844156429', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 7, 7, 'God, when you went forth before your people, when you marched through the wilderness... Selah.'),
  ('20be0f14-33a1-5be7-acce-62253260fe6f', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 8, 8, 'The earth trembled. The sky also poured down rain at the presence of the God of Sinai-- at the presence of God, the God of Israel.'),
  ('378fa9d7-448d-5300-a696-51db7620754c', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 9, 9, 'You, God, sent a plentiful rain. You confirmed your inheritance, when it was weary.'),
  ('57f39fee-7cd1-5b1c-a623-dc250b381178', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 10, 10, 'Your congregation lived therein. You, God, prepared your goodness for the poor.'),
  ('202c523d-44cd-596e-a274-345f3c295d24', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 11, 11, 'The Lord announced the word. The ones who proclaim it are a great company.'),
  ('eebc848e-eae7-5693-a4b6-6346713ed88a', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 12, 12, '"Kings of armies flee! They flee!" She who waits at home divides the spoil,'),
  ('97a1cd08-82b6-5f5a-a529-def86252bdc7', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 13, 13, 'while you sleep among the campfires, the wings of a dove sheathed with silver, her feathers with shining gold.'),
  ('2bc3e3aa-661d-56e1-aec1-3d9dd71bc99c', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 14, 14, 'When the Almighty scattered kings in her, it snowed on Zalmon.'),
  ('2bf8a007-8982-51f7-ae5e-05536e20da7f', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 15, 15, 'The mountains of Bashan are majestic mountains. The mountains of Bashan are rugged.'),
  ('97efb4a1-8246-5070-a033-ef1797712f42', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 16, 16, 'Why do you look in envy, you rugged mountains, at the mountain where God chooses to reign? Yes, Yahweh will dwell there forever.'),
  ('11a0d4c5-d862-5d91-a94b-b86797b035e2', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 17, 17, 'The chariots of God are tens of thousands and thousands of thousands. The Lord is among them, from Sinai, into the sanctuary.'),
  ('0651c46c-8fd7-5663-a03c-5bee03a499d5', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 18, 18, 'You have ascended on high. You have led away captives. You have received gifts among men, yes, among the rebellious also, that Yah God might dwell there.'),
  ('f53f527c-7820-5df2-a926-6128a0cc8251', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 19, 19, 'Blessed be the Lord, who daily bears our burdens, even the God who is our salvation. Selah.'),
  ('eaea09fc-52d6-569b-ab7b-348d48c30883', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 20, 20, 'God is to us a God of deliverance. To Yahweh, the Lord, belongs escape from death.'),
  ('cf3fe8eb-583d-52d5-aba5-69e401f79f91', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 21, 21, 'But God will strike through the head of his enemies, the hairy scalp of such a one as still continues in his guiltiness.'),
  ('a67ad8cf-7aa7-545c-a37c-ea379962c96e', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 22, 22, 'The Lord said, "I will bring you again from Bashan, I will bring you again from the depths of the sea;'),
  ('0fc9f4bf-b709-52c8-ae29-a3c3f7d7f0a1', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 23, 23, 'That you may crush them, dipping your foot in blood, that the tongues of your dogs may have their portion from your enemies."'),
  ('22388510-62fe-52b6-adf7-56b8c181ebce', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 24, 24, 'They have seen your processions, God, even the processions of my God, my King, into the sanctuary.'),
  ('5b115da5-fb2a-56e7-a3d4-a62bf1a13ec9', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 25, 25, 'The singers went before, the minstrels followed after, in the midst of the ladies playing with tambourines,'),
  ('e372546c-bd75-555b-aba5-561795617694', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 26, 26, '"Bless God in the congregations, even the Lord in the assembly of Israel!"'),
  ('548f7bad-2f58-5f66-a89c-52a532ed264b', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 27, 27, 'There is little Benjamin, their ruler, the princes of Judah, their council, the princes of Zebulun, and the princes of Naphtali.'),
  ('a82c914e-3f79-55f0-aa92-2baf4fb4c16b', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 28, 28, 'Your God has commanded your strength. Strengthen, God, that which you have done for us.'),
  ('5d53fdd7-9823-5d15-a3d5-406e6a9ca6c3', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 29, 29, 'Because of your temple at Jerusalem, kings shall bring presents to you.'),
  ('473947b4-e8c4-5c5f-a7d3-5d1117dc8df1', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 30, 30, 'Rebuke the wild animal of the reeds, the multitude of the bulls, with the calves of the peoples. Being humbled, may it bring bars of silver. Scatter the nations that delight in war.'),
  ('3da61404-3dfa-5dd1-a404-26d78b396bdb', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 31, 31, 'Princes shall come out of Egypt. Ethiopia shall hurry to stretch out her hands to God.'),
  ('7689efb4-fd65-5a1b-a9d6-93ea2f5c516b', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 32, 32, 'Sing to God, you kingdoms of the earth! Sing praises to the Lord! Selah.'),
  ('9a331679-fce0-5fbc-a46b-ecd9162f19af', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 33, 33, 'To him who rides on the heaven of heavens, which are of old; behold, he utters his voice, a mighty voice.'),
  ('2eb29d9e-2847-573b-aa28-192b4d4553ed', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 34, 34, 'Ascribe strength to God! His excellency is over Israel, his strength is in the skies.'),
  ('32fc21ea-a6ef-56ab-a485-026f7edb7dba', 'db3d6e6a-ece6-505e-ad3f-b38a80c19d26', NULL, 35, 35, 'You are awesome, God, in your sanctuaries. The God of Israel gives strength and power to his people. Praise be to God! For the Chief Musician. To the tune of "Lilies." By David.'),
  ('8db6e507-1011-5b3c-a4b5-aed15f3b87e1', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 1, 1, 'Save me, God, for the waters have come up to my neck!'),
  ('334a2e99-c3d3-5548-a4a6-0cead9389d0d', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 2, 2, 'I sink in deep mire, where there is no foothold. I have come into deep waters, where the floods overflow me.'),
  ('6613032a-100d-531a-a97d-7da9f4a0edc2', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 3, 3, 'I am weary with my crying. My throat is dry. My eyes fail, looking for my God.'),
  ('ce0dfff2-61b6-5fd3-a834-98949d92dcca', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 4, 4, 'Those who hate me without a cause are more than the hairs of my head. Those who want to cut me off, being my enemies wrongfully, are mighty. I have to restore what I didn''t take away.'),
  ('cdef24a7-7ee5-593f-aa8b-f2bdbf18954d', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 5, 5, 'God, you know my foolishness. My sins aren''t hidden from you.'),
  ('e1533a83-158b-54c6-ac8c-e02cdf702d03', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 6, 6, 'Don''t let those who wait for you be shamed through me, Lord Yahweh of Armies. Don''t let those who seek you be brought to dishonor through me, God of Israel.'),
  ('bfd889a2-a274-5edb-a6fa-721561a02de0', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 7, 7, 'Because for your sake, I have borne reproach. Shame has covered my face.'),
  ('d17f2cfa-ce43-5766-a914-4b8548965c1b', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 8, 8, 'I have become a stranger to my brothers, an alien to my mother''s children.'),
  ('6419cdef-c6c6-573c-ac57-5b2eaced1f4a', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 9, 9, 'For the zeal of your house consumes me. The reproaches of those who reproach you have fallen on me.'),
  ('659deb09-0cca-5a00-a512-4b39e5091de7', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 10, 10, 'When I wept and I fasted, that was to my reproach.'),
  ('0b407b1b-1394-5eec-a904-faa27b30ada9', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 11, 11, 'When I made sackcloth my clothing, I became a byword to them.'),
  ('3dceee23-f4d8-54a3-aa9d-39f1ab80fa85', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 12, 12, 'Those who sit in the gate talk about me. I am the song of the drunkards.'),
  ('d1f6b9c5-1e0b-52ee-a39f-1e708dea1e34', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 13, 13, 'But as for me, my prayer is to you, Yahweh, in an acceptable time. God, in the abundance of your loving kindness, answer me in the truth of your salvation.'),
  ('1911e8aa-7aaa-5eae-a022-9f96949fffd5', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 14, 14, 'Deliver me out of the mire, and don''t let me sink. Let me be delivered from those who hate me, and out of the deep waters.'),
  ('7227ef55-7514-53ae-a76e-632728646c71', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 15, 15, 'Don''t let the flood waters overwhelm me, neither let the deep swallow me up. Don''t let the pit shut its mouth on me.'),
  ('edaf06b2-a1b5-53f8-a68a-e6eb226139b8', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 16, 16, 'Answer me, Yahweh, for your loving kindness is good. According to the multitude of your tender mercies, turn to me.'),
  ('f564ca55-bfa4-56fc-a746-8ed4816781a5', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 17, 17, 'Don''t hide your face from your servant, for I am in distress. Answer me speedily!'),
  ('2eca337c-2249-5238-af8e-b00a7b1d23bb', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 18, 18, 'Draw near to my soul, and redeem it. Ransom me because of my enemies.'),
  ('5de0e9b7-61e2-5d5f-aac4-4e3de68acdf3', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 19, 19, 'You know my reproach, my shame, and my dishonor. My adversaries are all before you.'),
  ('0bfb6c60-2d43-56c6-ad7d-a2f8ff1fc4bd', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 20, 20, 'Reproach has broken my heart, and I am full of heaviness. I looked for some to take pity, but there was none; for comforters, but I found none.'),
  ('19aaf76d-9150-5e20-a654-9345d2290746', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 21, 21, 'They also gave me gall for my food. In my thirst, they gave me vinegar to drink.'),
  ('34bcd29a-5735-5a5f-a254-717028bd4f01', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 22, 22, 'Let their table before them become a snare. May it become a retribution and a trap.'),
  ('76a66f6a-506d-5c84-ad7d-45f413746508', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 23, 23, 'Let their eyes be darkened, so that they can''t see. Let their backs be continually bent.'),
  ('36971040-bbc7-5220-a1fd-71ab95127e27', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 24, 24, 'Pour out your indignation on them. Let the fierceness of your anger overtake them.'),
  ('7812a63d-528c-5bf7-afe9-e39511ce2147', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 25, 25, 'Let their habitation be desolate. Let no one dwell in their tents.'),
  ('58f92515-1d63-5903-ad6e-41c596f5919d', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 26, 26, 'For they persecute him whom you have wounded. They tell of the sorrow of those whom you have hurt.'),
  ('95681595-a502-58ab-ad9a-9c1c75c12152', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 27, 27, 'Charge them with crime upon crime. Don''t let them come into your righteousness.'),
  ('cb5a0aa6-fa41-5d5c-ab0c-fc23c0b3068f', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 28, 28, 'Let them be blotted out of the book of life, and not be written with the righteous.'),
  ('2ebb5296-4339-5602-a8a9-60030f249ea4', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 29, 29, 'But I am in pain and distress. Let your salvation, God, protect me.'),
  ('1399cbea-59cd-5b67-a103-bd765e6a00ab', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 30, 30, 'I will praise the name of God with a song, and will magnify him with thanksgiving.'),
  ('6164c74b-8e14-55f6-aedd-fbd57a5e0682', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 31, 31, 'It will please Yahweh better than an ox, or a bull that has horns and hoofs.'),
  ('17f54669-9fb8-5567-addd-647662050a9b', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 32, 32, 'The humble have seen it, and are glad. You who seek after God, let your heart live.'),
  ('caabb2d9-1913-5382-a058-d0ca2faa2778', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 33, 33, 'For Yahweh hears the needy, and doesn''t despise his captive people.'),
  ('6864a1b0-9a60-5658-ae3f-c8ceeb25ce2c', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 34, 34, 'Let heaven and earth praise him; the seas, and everything that moves therein!'),
  ('dea27e61-d4e2-520b-ac23-30ee866785a3', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 35, 35, 'For God will save Zion, and build the cities of Judah. They shall settle there, and own it.'),
  ('728786c5-a7d8-59c6-a37e-b88c1ef6a6e4', 'dcfb07af-b140-51e2-aef0-962db6a429f4', NULL, 36, 36, 'The children also of his servants shall inherit it. Those who love his name shall dwell therein. For the Chief Musician. By David. A reminder.'),
  ('5168e8a7-cbbd-5ad9-a0c5-43431a538992', 'a1329666-9e98-5291-a2d1-fcdf6cba2c69', NULL, 1, 1, 'Hurry, God, to deliver me. Come quickly to help me, Yahweh.'),
  ('f73ac1bb-4c09-5167-af9e-7d3a38c4f634', 'a1329666-9e98-5291-a2d1-fcdf6cba2c69', NULL, 2, 2, 'Let them be disappointed and confounded who seek my soul. Let those who desire my ruin be turned back in disgrace.'),
  ('3c970fd1-e5ba-5960-a2ab-ecd9e63a5ff1', 'a1329666-9e98-5291-a2d1-fcdf6cba2c69', NULL, 3, 3, 'Let them be turned because of their shame Who say, "Aha! Aha!"'),
  ('b2151264-035d-5b9e-acb6-06e8ab328790', 'a1329666-9e98-5291-a2d1-fcdf6cba2c69', NULL, 4, 4, 'Let all those who seek you rejoice and be glad in you. Let those who love your salvation continually say, "Let God be exalted!"'),
  ('657e00c6-e9dd-580a-aba8-b57278fc4052', 'a1329666-9e98-5291-a2d1-fcdf6cba2c69', NULL, 5, 5, 'But I am poor and needy. Come to me quickly, God. You are my help and my deliverer. Yahweh, don''t delay.'),
  ('f7bdfaaf-ff92-58a3-ad0c-091181fddb12', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 1, 1, 'In you, Yahweh, I take refuge. Never let me be disappointed.'),
  ('1b66e143-e16e-5eda-ae8c-5d6da8a126f0', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 2, 2, 'Deliver me in your righteousness, and rescue me. Turn your ear to me, and save me.'),
  ('487a59e9-8a97-5dbe-af4c-02b166e250bb', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 3, 3, 'Be to me a rock of refuge to which I may always go. Give the command to save me, for you are my rock and my fortress.'),
  ('8fb6989d-fe74-5a3c-a926-a10d838aa27b', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 4, 4, 'Rescue me, my God, from the hand of the wicked, from the hand of the unrighteous and cruel man.'),
  ('07f060d0-c880-5a18-a1c9-14c43c804643', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 5, 5, 'For you are my hope, Lord Yahweh; my confidence from my youth.'),
  ('6cdd429f-c63b-5474-a8ec-c59595bd0ef7', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 6, 6, 'I have relied on you from the womb. You are he who took me out of my mother''s womb. I will always praise you.'),
  ('61883f35-70eb-5aaa-ae51-1b73a99539d3', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 7, 7, 'I am a marvel to many, but you are my strong refuge.'),
  ('02645c80-e7c4-537a-aa1f-e25f997ebd2a', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 8, 8, 'My mouth shall be filled with your praise, with your honor all the day.'),
  ('7cf647b6-a9e2-5600-a328-3eb6a93d28c2', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 9, 9, 'Don''t reject me in my old age. Don''t forsake me when my strength fails.'),
  ('24d1f422-92a8-5a09-aaf1-745aca9548f4', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 10, 10, 'For my enemies talk about me. Those who watch for my soul conspire together,'),
  ('8ae369ed-15e0-5264-a1a4-130acf97cc0f', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 11, 11, 'saying, "God has forsaken him. Pursue and take him, for no one will rescue him."'),
  ('09aec3af-facb-53b8-a5db-ae30faf0235e', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 12, 12, 'God, don''t be far from me. My God, hurry to help me.'),
  ('38f53ac4-7ac3-5ecb-adc5-5a38fa65e210', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 13, 13, 'Let my accusers be disappointed and consumed. Let them be covered with disgrace and scorn who want to harm me.'),
  ('8da17761-bddc-518e-aa33-3b3db6e43394', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 14, 14, 'But I will always hope, and will add to all of your praise.'),
  ('3694d75e-8056-567e-a536-c3e7857d696e', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 15, 15, 'My mouth will tell about your righteousness, and of your salvation all day, though I don''t know its full measure.'),
  ('8a3d4977-49d5-502c-a3b6-a905f3d42859', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 16, 16, 'I will come with the mighty acts of the Lord Yahweh. I will make mention of your righteousness, even of yours alone.'),
  ('414b24cc-f933-5ea5-ab43-c87bd45dac34', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 17, 17, 'God, you have taught me from my youth. Until now, I have declared your wondrous works.'),
  ('93906709-8201-5c81-a0d0-cfbd79dbda43', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 18, 18, 'Yes, even when I am old and gray-haired, God, don''t forsake me, until I have declared your strength to the next generation, your might to everyone who is to come.'),
  ('8ddb36f2-7100-52e2-ab4b-bc7a6048d18f', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 19, 19, 'Your righteousness also, God, reaches to the heavens; you have done great things. God, who is like you?'),
  ('113c47f5-13d6-53e0-a5ee-fe4e9c6405b2', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 20, 20, 'You, who have shown us many and bitter troubles, you will let me live. You will bring us up again from the depths of the earth.'),
  ('ad2e4eb7-d987-5a23-aff9-b9dd6335be1a', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 21, 21, 'Increase my honor, and comfort me again.'),
  ('be42c388-3644-500f-a752-1c6aaa81b223', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 22, 22, 'I will also praise you with the harp for your faithfulness, my God. I sing praises to you with the lyre, Holy One of Israel.'),
  ('0faa6d71-bcf7-5ae8-a121-d177629bb2fd', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 23, 23, 'My lips shall shout for joy! My soul, which you have redeemed, sings praises to you!'),
  ('58d52ad8-fe73-5304-a58a-bf79f8ce02d6', '6acd5c0f-d57a-5cdb-a702-e1aab3e18b7f', NULL, 24, 24, 'My tongue will also talk about your righteousness all day long, for they are disappointed, and they are confounded, who want to harm me. By Solomon.'),
  ('f3805d6c-a46b-58e6-a1fe-29fbbe7ab0e1', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 1, 1, 'God, give the king your justice; your righteousness to the royal son.'),
  ('f8a63de4-50fa-52a8-a60e-151c0dbb2259', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 2, 2, 'He will judge your people with righteousness, and your poor with justice.'),
  ('c56522c7-0b9f-5618-ac87-35f0cd5501db', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 3, 3, 'The mountains shall bring prosperity to the people. The hills bring the fruit of righteousness.'),
  ('699b7a7b-6c26-5805-a578-9598e076ec1a', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 4, 4, 'He will judge the poor of the people. He will save the children of the needy, and will break the oppressor in pieces.'),
  ('8d5cd02f-2bfb-5fcc-a7f7-117ad3faaca2', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 5, 5, 'They shall fear you while the sun endures; and as long as the moon, throughout all generations.'),
  ('0065f486-4826-5fd0-abaa-034b41deec9b', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 6, 6, 'He will come down like rain on the mown grass, as showers that water the earth.'),
  ('155a79ea-c8cb-5d1e-a127-5fb03d3ca899', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 7, 7, 'In his days, the righteous shall flourish, and abundance of peace, until the moon is no more.'),
  ('9247c69a-b3cc-569b-a9f9-bc5a9bdd420c', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 8, 8, 'He shall have dominion also from sea to sea, from the River to the ends of the earth.'),
  ('073a0ce1-d38a-5923-ae02-a14dc5fb8717', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 9, 9, 'Those who dwell in the wilderness shall bow before him. His enemies shall lick the dust.'),
  ('b9262f2e-1630-533f-a657-bb38c49c7d44', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 10, 10, 'The kings of Tarshish and of the islands will bring tribute. The kings of Sheba and Seba shall offer gifts.'),
  ('53f7a167-ef60-554d-ad39-fd8ee54b34f1', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 11, 11, 'Yes, all kings shall fall down before him. All nations shall serve him.'),
  ('027b603b-3539-58ad-a324-b30d1b3fd896', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 12, 12, 'For he will deliver the needy when he cries; the poor, who has no helper.'),
  ('1ebfdc80-75d8-5e8f-a0bd-1793cd2cdfe3', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 13, 13, 'He will have pity on the poor and needy. He will save the souls of the needy.'),
  ('eddd9335-8303-53f4-a291-2f146d9679ac', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 14, 14, 'He will redeem their soul from oppression and violence. Their blood will be precious in his sight.'),
  ('db8089ae-92f1-5719-a370-bd11d7edebc7', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 15, 15, 'They shall live, and to him shall be given of the gold of Sheba. Men shall pray for him continually. They shall bless him all day long.'),
  ('b7e381d7-3e2a-5d31-addd-61338616a00b', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 16, 16, 'Abundance of grain shall be throughout the land. Its fruit sways like Lebanon. Let it flourish, thriving like the grass of the field.'),
  ('64c2aa60-4145-522d-aaaa-70a5e167ce3b', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 17, 17, 'His name endures forever. His name continues as long as the sun. Men shall be blessed by him. All nations will call him blessed.'),
  ('1b9f5d53-298a-5f02-a739-90f033eb1a07', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 18, 18, 'Praise be to Yahweh God, the God of Israel, who alone does marvelous deeds.'),
  ('12f93c8e-cd49-53ee-ad24-e38650376766', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 19, 19, 'Blessed be his glorious name forever! Let the whole earth be filled with his glory! Amen and amen.'),
  ('d8b2078f-cc10-5911-a023-c0b763754bc3', '4509a2f4-bb9e-5ba2-aabe-511b3ee63831', NULL, 20, 20, 'This ends the prayers by David, the son of Jesse. BOOK III A Psalm by Asaph.'),
  ('ace14805-99cd-5b00-adb2-6eb83e4bc23e', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 1, 1, 'Surely God is good to Israel, to those who are pure in heart.'),
  ('6d5a0ce7-fde7-59c0-ab41-a86e302b8f6d', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 2, 2, 'But as for me, my feet were almost gone. My steps had nearly slipped.'),
  ('28b0a6c3-1b0e-5773-ad26-f95b1b8d2166', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 3, 3, 'For I was envious of the arrogant, when I saw the prosperity of the wicked.'),
  ('19839ecb-d8b2-5daf-ad58-cf74f363fcc1', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 4, 4, 'For there are no struggles in their death, but their strength is firm.'),
  ('7e14d76e-85f4-5736-ab93-4356dcfe9103', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 5, 5, 'They are free from burdens of men, neither are they plagued like other men.'),
  ('30c78fe1-5ab2-50ec-a1c1-831b302a16f4', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 6, 6, 'Therefore pride is like a chain around their neck. Violence covers them like a garment.'),
  ('895b2159-808f-5330-ab26-3f1c117e6b5f', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 7, 7, 'Their eyes bulge with fat. Their minds pass the limits of conceit.'),
  ('8b6fc6d2-39b4-502a-a104-d672f2ffef9a', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 8, 8, 'They scoff and speak with malice. In arrogance, they threaten oppression.'),
  ('9184e15d-6a40-5332-a382-7da6874a747c', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 9, 9, 'They have set their mouth in the heavens. Their tongue walks through the earth.'),
  ('b0b50834-29b6-57e2-a85e-d60f625aacd5', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 10, 10, 'Therefore their people return to them, and they drink up waters of abundance.'),
  ('e65ee978-3a66-599c-a1ec-69263c9a1cd9', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 11, 11, 'They say, "How does God know? Is there knowledge in the Most High?"'),
  ('0e9b298b-ef82-5ff2-ab79-60f022ed805d', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 12, 12, 'Behold, these are the wicked. Being always at ease, they increase in riches.'),
  ('e416cd6c-d24f-59de-afbe-987558d4f725', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 13, 13, 'Surely in vain I have cleansed my heart, and washed my hands in innocence,'),
  ('8368f87a-5d32-55cd-a708-b0b8da6f0076', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 14, 14, 'For all day long have I been plagued, and punished every morning.'),
  ('60bbd59f-6ed5-5b2b-a987-6a883a875a59', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 15, 15, 'If I had said, "I will speak thus;" behold, I would have betrayed the generation of your children.'),
  ('a88f9570-1cad-5946-a9d2-a614b8941fa8', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 16, 16, 'When I tried to understand this, it was too painful for me;'),
  ('253a48a1-964e-5a15-a490-514a288633fe', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 17, 17, 'Until I entered God''s sanctuary, and considered their latter end.'),
  ('12d81b43-931e-512f-a585-b1c80bee0190', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 18, 18, 'Surely you set them in slippery places. You throw them down to destruction.'),
  ('2c62be9d-b6bc-5016-aa7d-6003bcd3c8bf', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 19, 19, 'How they are suddenly destroyed! They are completely swept away with terrors.'),
  ('205ed3ed-2df3-5fdf-aead-02aeb5ccb4c6', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 20, 20, 'As a dream when one wakes up, so, Lord, when you awake, you will despise their fantasies.'),
  ('45eabc7e-901c-539d-a6db-afc58b236f77', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 21, 21, 'For my soul was grieved. I was embittered in my heart.'),
  ('c2581a02-50e3-58f8-acb4-4106085715b9', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 22, 22, 'I was so senseless and ignorant. I was a brute beast before you.'),
  ('b18d5952-4b2d-53bf-ae54-8750fb3b4ae7', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 23, 23, 'Nevertheless, I am continually with you. You have held my right hand.'),
  ('2b3b6677-0b11-5f78-adf6-636c8217a435', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 24, 24, 'You will guide me with your counsel, and afterward receive me to glory.'),
  ('925c9505-e5d1-5b70-a934-009155229cfc', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 25, 25, 'Who do I have in heaven? There is no one on earth who I desire besides you.'),
  ('bfbe1c8d-6fd3-5387-a4ca-55b1f8108d2d', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 26, 26, 'My flesh and my heart fails, but God is the strength of my heart and my portion forever.'),
  ('88e674e8-af02-58a6-a68f-5d725f408f62', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 27, 27, 'For, behold, those who are far from you shall perish. You have destroyed all those who are unfaithful to you.'),
  ('95b0c4f6-209e-5088-ad32-0e1bbb8d0f88', 'e23812e1-53ad-57c6-aa94-47117d321f09', NULL, 28, 28, 'But it is good for me to come close to God. I have made the Lord Yahweh my refuge, that I may tell of all your works. A contemplation by Asaph.'),
  ('94236013-9c90-587a-a985-e4ab35b8ea4b', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 1, 1, 'God, why have you rejected us forever? Why does your anger smolder against the sheep of your pasture?'),
  ('84b2f6ff-1936-5a30-a409-55c9457fd23b', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 2, 2, 'Remember your congregation, which you purchased of old, which you have redeemed to be the tribe of your inheritance; Mount Zion, in which you have lived.'),
  ('b88e16d6-4ced-5298-acfd-d6b026681371', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 3, 3, 'Lift up your feet to the perpetual ruins, all the evil that the enemy has done in the sanctuary.'),
  ('d7162a4e-847f-5a7e-ad2f-3c6a2415a613', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 4, 4, 'Your adversaries have roared in the midst of your assembly. They have set up their standards as signs.'),
  ('33543ec8-3a07-54b9-abb6-762e9b55cd21', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 5, 5, 'They behaved like men wielding axes, cutting through a thicket of trees.'),
  ('11c91e73-8cbc-5616-a8f2-e717a17a9c45', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 6, 6, 'Now they break all its carved work down with hatchet and hammers.'),
  ('8ebb110e-c376-5c40-a699-ebcc3a981182', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 7, 7, 'They have burned your sanctuary to the ground. They have profaned the dwelling place of your Name.'),
  ('f6b21f65-991c-575f-aa2a-4c15c29eb257', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 8, 8, 'They said in their heart, "We will crush them completely." They have burned up all the places in the land where God was worshiped.'),
  ('9ff5dadd-23fc-53f0-a801-e3a659f0e5e2', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 9, 9, 'We see no miraculous signs. There is no longer any prophet, neither is there among us anyone who knows how long.'),
  ('c4d87d13-806a-51e1-a2dd-fa31bc01157f', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 10, 10, 'How long, God, shall the adversary reproach? Shall the enemy blaspheme your name forever?'),
  ('87f473e9-db42-5175-a520-51e02c8af451', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 11, 11, 'Why do you draw back your hand, even your right hand? Take it out of your pocket and consume them!'),
  ('2cbe6c18-cf96-5776-adc1-85efa6852c91', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 12, 12, 'Yet God is my King of old, working salvation in the midst of the earth.'),
  ('35989ba6-805c-5f51-a667-8754e84193ff', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 13, 13, 'You divided the sea by your strength. You broke the heads of the sea monsters in the waters.'),
  ('e65003bf-4979-594f-a53a-19594a3e9e4a', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 14, 14, 'You broke the heads of Leviathan in pieces. You gave him as food to people and desert creatures.'),
  ('71f86845-45a1-5913-a5d8-737ea2aa148c', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 15, 15, 'You opened up spring and stream. You dried up mighty rivers.'),
  ('87d4357d-1e74-579a-a65b-98a75ce202ab', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 16, 16, 'The day is yours, the night is also yours. You have prepared the light and the sun.'),
  ('00cbc04d-bc6c-5c01-afa9-b7e7a008942c', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 17, 17, 'You have set all the boundaries of the earth. You have made summer and winter.'),
  ('a42c3b70-f5f1-5604-a5ca-c4ee564ee918', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 18, 18, 'Remember this, that the enemy has mocked you, Yahweh. Foolish people have blasphemed your name.'),
  ('bd7bed2a-bf68-5cc2-a09c-32ae6ffc9680', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 19, 19, 'Don''t deliver the soul of your dove to wild beasts. Don''t forget the life of your poor forever.'),
  ('2d775306-2c8c-5c44-a543-374026d4e2f4', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 20, 20, 'Honor your covenant, for haunts of violence fill the dark places of the earth.'),
  ('2782f9a9-ccdc-546b-a90b-9e8961009c9e', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 21, 21, 'Don''t let the oppressed return ashamed. Let the poor and needy praise your name.'),
  ('862d7772-a432-5350-a408-2c6e98277157', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 22, 22, 'Arise, God! Plead your own cause. Remember how the foolish man mocks you all day.'),
  ('60c1f4fc-5a5e-5ccb-a18a-9903a2ece517', 'eb32b71b-c6a3-5dc6-a683-cd956b107a33', NULL, 23, 23, 'Don''t forget the voice of your adversaries. The tumult of those who rise up against you ascends continually. For the Chief Musician. To the tune of "Do Not Destroy." A Psalm by Asaph. A song.'),
  ('dca55d02-5b43-5edd-ad58-c578d83cdde0', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 1, 1, 'We give thanks to you, God. We give thanks, for your Name is near. Men tell about your wondrous works.'),
  ('f16e0588-c9b2-517a-adeb-91b9f3801b3f', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 2, 2, 'When I choose the appointed time, I will judge blamelessly.'),
  ('d50d25e2-0882-5db0-aa33-3202f98cadd0', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 3, 3, 'The earth and all its inhabitants quake. I firmly hold its pillars. Selah.'),
  ('2ae49ecc-c0e4-58c0-a3c4-cee41a9c6792', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 4, 4, 'I said to the arrogant, "Don''t boast!" I said to the wicked, "Don''t lift up the horn.'),
  ('f0c959f5-2f3c-5527-a144-2695656f26a6', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 5, 5, 'Don''t lift up your horn on high. Don''t speak with a stiff neck."'),
  ('5c46d7f8-8af5-5970-a211-1c6d1b08973f', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 6, 6, 'For neither from the east, nor from the west, nor yet from the south, comes exaltation.'),
  ('37c32ce5-e532-5cbd-acea-f363244eb2f8', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 7, 7, 'But God is the judge. He puts down one, and lifts up another.'),
  ('e20055e8-f064-5169-a2d6-51894b08bee9', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 8, 8, 'For in the hand of Yahweh there is a cup, full of foaming wine mixed with spices. He pours it out. Indeed the wicked of the earth drink and drink it to its very dregs.'),
  ('02885eac-ab4f-52f9-aa9f-ad4bd324b2de', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 9, 9, 'But I will declare this forever: I will sing praises to the God of Jacob.'),
  ('33c5400e-778a-52d8-aa6b-cededa240958', '7f1e8ee0-158c-5f22-a411-24afc7b022aa', NULL, 10, 10, 'I will cut off all the horns of the wicked, but the horns of the righteous shall be lifted up. For the Chief Musician. On stringed instruments. A Psalm by Asaph. A song.'),
  ('ee623e1b-f7ca-5b50-aaf7-8f1813a45b42', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 1, 1, 'In Judah, God is known. His name is great in Israel.'),
  ('1af1ce5d-6f63-5230-a0b7-5967700d4e14', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 2, 2, 'His tabernacle is also in Salem; His dwelling place in Zion.'),
  ('88394f09-95c9-5adc-a0b5-22f12cd3ba84', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 3, 3, 'There he broke the flaming arrows of the bow, the shield, and the sword, and the weapons of war. Selah.'),
  ('f2cfd652-30aa-5e06-a950-5f91be84e534', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 4, 4, 'Glorious are you, and excellent, more than mountains of game.'),
  ('8d48f60a-b092-5f17-abaf-d4526062dbc7', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 5, 5, 'Valiant men lie plundered, they have slept their last sleep. None of the men of war can lift their hands.'),
  ('1334db15-6e85-50c8-aae4-0ef32aef0f97', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 6, 6, 'At your rebuke, God of Jacob, both chariot and horse are cast into a deep sleep.'),
  ('e54a608f-0df8-563a-a054-f348a111b432', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 7, 7, 'You, even you, are to be feared. Who can stand in your sight when you are angry?'),
  ('f08c49cf-f711-58ed-a341-392a8bf0765e', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 8, 8, 'You pronounced judgment from heaven. The earth feared, and was silent,'),
  ('d49ccda9-4d6f-5e15-af7b-1a2b9abd78f0', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 9, 9, 'when God arose to judgment, to save all the afflicted ones of the earth. Selah.'),
  ('aea93ec4-4243-5898-aec5-a34411969b5b', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 10, 10, 'Surely the wrath of man praises you. The survivors of your wrath are restrained.'),
  ('1559cbea-08f4-5974-a273-9b489296dbb4', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 11, 11, 'Make vows to Yahweh your God, and fulfill them! Let all of his neighbors bring presents to him who is to be feared.'),
  ('f951a6c2-4790-5e05-a388-fa7a2d881365', '4fb879cb-b7dd-5f21-adb5-2bebc3b0f473', NULL, 12, 12, 'He will cut off the spirit of princes. He is feared by the kings of the earth. For the Chief Musician. To Jeduthun. A Psalm by Asaph.'),
  ('53c7924a-e478-5349-a0a6-a17605d17b9a', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 1, 1, 'My cry goes to God! Indeed, I cry to God for help, and for him to listen to me.'),
  ('b94ea951-ad55-567a-ae62-c361da411774', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 2, 2, 'In the day of my trouble I sought the Lord. My hand was stretched out in the night, and didn''t get tired. My soul refused to be comforted.'),
  ('507b1918-6ced-5712-a8c6-20937187f04c', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 3, 3, 'I remember God, and I groan. I complain, and my spirit is overwhelmed. Selah.'),
  ('0d45a7be-67ee-55a8-a9ce-99e613b75eb0', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 4, 4, 'You hold my eyelids open. I am so troubled that I can''t speak.'),
  ('d6d16ecb-0484-5192-aabe-1296e02bbfd4', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 5, 5, 'I have considered the days of old, the years of ancient times.'),
  ('b5f376bd-f28b-5ea2-a5fc-bb87364bb890', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 6, 6, 'I remember my song in the night. I consider in my own heart; my spirit diligently inquires:'),
  ('778dab16-2a51-55c8-a761-70cfd2b38000', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 7, 7, '"Will the Lord reject us forever? Will he be favorable no more?'),
  ('436af7e8-21d4-579a-a377-aa886efe346b', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 8, 8, 'Has his loving kindness vanished forever? Does his promise fail for generations?'),
  ('d7d07645-c61e-5b18-aa2f-ed203641db1e', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 9, 9, 'Has God forgotten to be gracious? Has he, in anger, withheld his compassion?" Selah.'),
  ('76684734-5eb6-52a2-ad30-0b1594a112ed', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 10, 10, 'Then I thought, "I will appeal to this: the years of the right hand of the Most High."'),
  ('5d336bbe-c73d-5cfd-a04c-d0ac651afc57', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 11, 11, 'I will remember Yah''s deeds; for I will remember your wonders of old.'),
  ('22385abe-4224-51a5-a7cc-dec845ffed1e', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 12, 12, 'I will also meditate on all your work, and consider your doings.'),
  ('8bd8ef4d-4fbb-5fbb-a1e9-931d28823d5a', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 13, 13, 'Your way, God, is in the sanctuary. What god is great like God?'),
  ('16a25cf5-d2d6-54bb-aa8f-a98f8433bc38', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 14, 14, 'You are the God who does wonders. You have made your strength known among the peoples.'),
  ('f8772d9b-c5dc-5790-ae84-de700ae5c996', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 15, 15, 'You have redeemed your people with your arm, the sons of Jacob and Joseph. Selah.'),
  ('d53b49eb-0dc2-5398-a33a-a3435346a4d4', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 16, 16, 'The waters saw you, God. The waters saw you, and they writhed. The depths also convulsed.'),
  ('3c2d279b-8435-5942-a894-06d37117a9d7', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 17, 17, 'The clouds poured out water. The skies resounded with thunder. Your arrows also flashed around.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('1d872d21-cf3d-529a-ace5-153a690a1d1f', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 18, 18, 'The voice of your thunder was in the whirlwind. The lightnings lit up the world. The earth trembled and shook.'),
  ('5d9f007e-76a8-5784-a93e-30dae3740cf5', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 19, 19, 'Your way was through the sea; your paths through the great waters. Your footsteps were not known.'),
  ('1721a113-aa3c-5488-a855-267465b17db1', 'c8f03b9a-8234-5e0c-ae90-a964e82438f1', NULL, 20, 20, 'You led your people like a flock, by the hand of Moses and Aaron. A contemplation by Asaph.'),
  ('2ee32615-6263-5911-a6d8-9c432c44b6b6', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 1, 1, 'Hear my teaching, my people. Turn your ears to the words of my mouth.'),
  ('93bb802b-6ce3-5632-ad44-a737f76924ce', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 2, 2, 'I will open my mouth in a parable. I will utter dark sayings of old,'),
  ('0ab2a50e-4bbf-5a49-a22f-7f37e8f8c1a9', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 3, 3, 'Which we have heard and known, and our fathers have told us.'),
  ('7e6c6ef1-60f4-57a5-a9af-d6e24d831373', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 4, 4, 'We will not hide them from their children, telling to the generation to come the praises of Yahweh, his strength, and his wondrous works that he has done.'),
  ('45e5d037-6a46-56da-a0bc-8023f1452c5e', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 5, 5, 'For he established a testimony in Jacob, and appointed a teaching in Israel, which he commanded our fathers, that they should make them known to their children;'),
  ('2a91987d-64c0-59bc-ad20-ac0e3c10d0bc', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 6, 6, 'that the generation to come might know, even the children who should be born; who should arise and tell their children,'),
  ('f3fe46e6-f736-518a-a80d-ee5d563d955b', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 7, 7, 'that they might set their hope in God, and not forget the works of God, but keep his commandments,'),
  ('ef2acef7-75fd-53d9-a4c2-da7434c84b74', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 8, 8, 'and might not be as their fathers, a stubborn and rebellious generation, a generation that didn''t make their hearts loyal, whose spirit was not steadfast with God.'),
  ('69b661d5-12bc-5cd7-a18a-8ca8a8ff0a51', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 9, 9, 'The children of Ephraim, being armed and carrying bows, turned back in the day of battle.'),
  ('744353c5-9774-5b88-acd9-0d0371951c7a', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 10, 10, 'They didn''t keep God''s covenant, and refused to walk in his law.'),
  ('3a158595-171e-52fe-a5c9-5a5f1ea1d427', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 11, 11, 'They forgot his doings, his wondrous works that he had shown them.'),
  ('26a6bd54-a30c-5ca2-a9d6-1f1d292bcae5', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 12, 12, 'He did marvelous things in the sight of their fathers, in the land of Egypt, in the field of Zoan.'),
  ('0a249fc7-9fa0-5517-a514-ec8b70b1e1a5', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 13, 13, 'He split the sea, and caused them to pass through. He made the waters stand as a heap.'),
  ('30ee26c6-4f0b-514c-a191-71fa906d79c3', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 14, 14, 'In the daytime he also led them with a cloud, and all night with a light of fire.'),
  ('ec5c5745-a316-572b-ace1-b0d40b473e92', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 15, 15, 'He split rocks in the wilderness, and gave them drink abundantly as out of the depths.'),
  ('c03f608b-62ca-5c31-a0fa-afc6f5b7c6e2', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 16, 16, 'He brought streams also out of the rock, and caused waters to run down like rivers.'),
  ('9ef428d0-ffb9-54ef-aa65-1fc6bcb4dd62', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 17, 17, 'Yet they still went on to sin against him, to rebel against the Most High in the desert.'),
  ('8fc4700e-0fd5-51e2-a91a-c4a909591c4f', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 18, 18, 'They tempted God in their heart by asking food according to their desire.'),
  ('d54067f9-60fd-5aea-a5fa-c8d1afc1d69a', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 19, 19, 'Yes, they spoke against God. They said, "Can God prepare a table in the wilderness?'),
  ('616d8384-fba2-5a23-ae3d-38bf7137621e', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 20, 20, 'Behold, he struck the rock, so that waters gushed out, and streams overflowed. Can he give bread also? Will he provide flesh for his people?"'),
  ('77989a5a-31b2-51d5-a90a-0919211150c0', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 21, 21, 'Therefore Yahweh heard, and was angry. A fire was kindled against Jacob, anger also went up against Israel,'),
  ('519fd74a-d39d-55d0-a53d-35713e68f995', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 22, 22, 'because they didn''t believe in God, and didn''t trust in his salvation.'),
  ('e2bb9183-1f39-539b-a57e-82f21b8624bc', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 23, 23, 'Yet he commanded the skies above, and opened the doors of heaven.'),
  ('7b096b6a-5d37-5fc4-a00d-40ae40154454', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 24, 24, 'He rained down manna on them to eat, and gave them food from the sky.'),
  ('0030f3bb-0634-589a-a716-d470151fe555', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 25, 25, 'Man ate the bread of angels. He sent them food to the full.'),
  ('c4180cec-a8c7-5047-a846-7ac155596bd6', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 26, 26, 'He caused the east wind to blow in the sky. By his power he guided the south wind.'),
  ('02c4cdc0-3c2f-5eee-a0ed-aa4325b6fc77', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 27, 27, 'He rained also flesh on them as the dust; winged birds as the sand of the seas.'),
  ('457bf083-84d2-56a2-a8d3-b2a27fb83990', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 28, 28, 'He let them fall in the midst of their camp, around their habitations.'),
  ('fad3baf2-4b8f-5fcf-a14b-32bebc8f3b2b', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 29, 29, 'So they ate, and were well filled. He gave them their own desire.'),
  ('ccf1a7eb-ca10-5e2f-a48d-e1c3367f87f7', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 30, 30, 'They didn''t turn from their cravings. Their food was yet in their mouths,'),
  ('099e3570-02c6-589a-ae75-801637527366', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 31, 31, 'when the anger of God went up against them, killed some of the fattest of them, and struck down the young men of Israel.'),
  ('672e1444-58f7-5ed2-aa89-2f3ae5ed1e68', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 32, 32, 'For all this they still sinned, and didn''t believe in his wondrous works.'),
  ('ef0e4313-09f4-5662-a7b4-ae5f163bdc03', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 33, 33, 'Therefore he consumed their days in vanity, and their years in terror.'),
  ('d99ad282-c7a3-54c9-ac05-ecfbf7a596ba', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 34, 34, 'When he killed them, then they inquired after him. They returned and sought God earnestly.'),
  ('b977fd69-e359-5574-afd6-dba4a6bdde32', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 35, 35, 'They remembered that God was their rock, the Most High God, their redeemer.'),
  ('e9f7f1e1-4cef-5be4-a391-c421f448c72a', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 36, 36, 'But they flattered him with their mouth, and lied to him with their tongue.'),
  ('cdfd54f3-7cbd-58fd-a460-7e3a66e8ff52', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 37, 37, 'For their heart was not right with him, neither were they faithful in his covenant.'),
  ('c7a7f813-ca8a-55e9-acfa-d0f94bb14a8b', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 38, 38, 'But he, being merciful, forgave iniquity, and didn''t destroy them. Yes, many times he turned his anger away, and didn''t stir up all his wrath.'),
  ('ea51c31c-035c-5ccc-abc1-4b0645f1dea8', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 39, 39, 'He remembered that they were but flesh, a wind that passes away, and doesn''t come again.'),
  ('bb90107d-f648-5dcb-a0c5-895a8b07ff51', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 40, 40, 'How often they rebelled against him in the wilderness, and grieved him in the desert!'),
  ('314a0071-ed69-545c-a86d-5bfbf6a2c02b', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 41, 41, 'They turned again and tempted God, and provoked the Holy One of Israel.'),
  ('99555273-ba59-5f1a-a6bd-74e3d2f09362', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 42, 42, 'They didn''t remember his hand, nor the day when he redeemed them from the adversary;'),
  ('0e1f88c1-73e7-55f8-af4b-84402a29a942', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 43, 43, 'how he set his signs in Egypt, his wonders in the field of Zoan,'),
  ('87591ac2-c7ce-5dfc-aeff-768923f33d0c', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 44, 44, 'he turned their rivers into blood, and their streams, so that they could not drink.'),
  ('25235918-f45f-5cd6-a3d4-860ef81e0abf', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 45, 45, 'He sent among them swarms of flies, which devoured them; and frogs, which destroyed them.'),
  ('feab015f-cfde-5fa5-ae06-ebbcb2e1fc25', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 46, 46, 'He gave also their increase to the caterpillar, and their labor to the locust.'),
  ('7f7a010e-8e78-5fef-aa39-6c700decb317', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 47, 47, 'He destroyed their vines with hail, their sycamore fig trees with frost.'),
  ('040ca2ca-7eec-5f8b-a750-de150dc4ae7a', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 48, 48, 'He gave over their livestock also to the hail, and their flocks to hot thunderbolts.'),
  ('73b91f30-974f-56da-ac2b-5b8bbcf02b55', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 49, 49, 'He threw on them the fierceness of his anger, wrath, indignation, and trouble, and a band of angels of evil.'),
  ('82a7d0e3-266d-5d2b-a726-ce225c937be0', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 50, 50, 'He made a path for his anger. He didn''t spare their soul from death, but gave their life over to the pestilence,'),
  ('466a9125-64ef-510a-afd5-7a5385337bf9', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 51, 51, 'and struck all the firstborn in Egypt, the chief of their strength in the tents of Ham.'),
  ('fd9c4458-99d7-5e43-a314-ed8110f73496', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 52, 52, 'But he led forth his own people like sheep, and guided them in the wilderness like a flock.'),
  ('98b0599f-a00e-5dda-a6e1-668fecc4505a', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 53, 53, 'He led them safely, so that they weren''t afraid, but the sea overwhelmed their enemies.'),
  ('92fb2958-1cee-597c-ad5d-2fef07f12a56', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 54, 54, 'He brought them to the border of his sanctuary, to this mountain, which his right hand had taken.'),
  ('f036bb4d-3cca-56f4-a43a-f7f15e6c61ac', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 55, 55, 'He also drove out the nations before them, allotted them for an inheritance by line, and made the tribes of Israel to dwell in their tents.'),
  ('f52b2c04-c01f-590b-ad23-ab5da75ee23e', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 56, 56, 'Yet they tempted and rebelled against the Most High God, and didn''t keep his testimonies;'),
  ('f3fecfa6-2c6c-556d-a2a2-5a4a2dd31dba', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 57, 57, 'but turned back, and dealt treacherously like their fathers. They were turned aside like a deceitful bow.'),
  ('3036e195-f8ba-5c05-a7e9-154ff9f1faeb', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 58, 58, 'For they provoked him to anger with their high places, and moved him to jealousy with their engraved images.'),
  ('1f0d26db-842d-5402-a778-39ca99958237', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 59, 59, 'When God heard this, he was angry, and greatly abhorred Israel;'),
  ('26334280-1e8d-522d-a988-27c0d98dedbe', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 60, 60, 'So that he forsook the tent of Shiloh, the tent which he placed among men;'),
  ('d17f1ffe-314b-5ab7-ac17-b59e065b0be6', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 61, 61, 'and delivered his strength into captivity, his glory into the adversary''s hand.'),
  ('ba37699e-956c-52a8-a484-1f1c075c191b', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 62, 62, 'He also gave his people over to the sword, and was angry with his inheritance.'),
  ('07cc1336-9ed9-54eb-a0fb-35ca46fa6b3e', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 63, 63, 'Fire devoured their young men. Their virgins had no wedding song.'),
  ('daa0a674-f9ea-5394-ab4d-931b4fa15190', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 64, 64, 'Their priests fell by the sword, and their widows couldn''t weep.'),
  ('7fba226a-fca5-5705-a243-6711f81d2d42', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 65, 65, 'Then the Lord awakened as one out of sleep, like a mighty man who shouts by reason of wine.'),
  ('0cd073a0-d0e2-5fcd-aa2a-821d618c6957', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 66, 66, 'He struck his adversaries backward. He put them to a perpetual reproach.'),
  ('758f3c89-9fbd-580c-a777-ed93e746e3c0', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 67, 67, 'Moreover he rejected the tent of Joseph, and didn''t choose the tribe of Ephraim,'),
  ('e2bb0100-9ae9-5738-ab6b-ecdfe9248c2b', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 68, 68, 'But chose the tribe of Judah, Mount Zion which he loved.'),
  ('4ffec381-0096-5048-a6cc-46f7027fa6f2', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 69, 69, 'He built his sanctuary like the heights, like the earth which he has established forever.'),
  ('750c1e80-acf3-56e4-a392-30df66fbdddd', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 70, 70, 'He also chose David his servant, and took him from the sheepfolds;'),
  ('f637e50d-f0dd-5709-a9c4-72bc9f54ddbc', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 71, 71, 'from following the ewes that have their young, he brought him to be the shepherd of Jacob, his people, and Israel, his inheritance.'),
  ('409de951-9454-5a74-a448-fbc660540e51', '8ef2fcd3-7982-5b04-a25a-7a6a644d3137', NULL, 72, 72, 'So he was their shepherd according to the integrity of his heart, and guided them by the skillfulness of his hands. A Psalm by Asaph.'),
  ('fb6cd4d2-8ff9-5167-af1c-541607f3214b', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 1, 1, 'God, the nations have come into your inheritance. They have defiled your holy temple. They have laid Jerusalem in heaps.'),
  ('9059fe2d-4bbc-5915-ae4f-01797adf9455', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 2, 2, 'They have given the dead bodies of your servants to be food for the birds of the sky, the flesh of your saints to the animals of the earth.'),
  ('30292115-e74f-52a9-afc1-32ecaa2236fa', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 3, 3, 'Their blood they have shed like water around Jerusalem. There was no one to bury them.'),
  ('43b5dab5-1541-566e-afcc-154e52957837', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 4, 4, 'We have become a reproach to our neighbors, a scoffing and derision to those who are around us.'),
  ('202f6536-2f8c-50fb-a5fe-ec0bebfb03f1', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 5, 5, 'How long, Yahweh? Will you be angry forever? Will your jealousy burn like fire?'),
  ('c9681a48-5966-5c56-a323-fbae34fa97a0', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 6, 6, 'Pour out your wrath on the nations that don''t know you; on the kingdoms that don''t call on your name;'),
  ('a1a3f726-7758-540e-a879-1fe679d8db4b', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 7, 7, 'For they have devoured Jacob, and destroyed his homeland.'),
  ('a3aab9a9-8906-52ba-a2f9-696b9a6d8592', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 8, 8, 'Don''t hold the iniquities of our forefathers against us. Let your tender mercies speedily meet us, for we are in desperate need.'),
  ('e59d0d12-10ca-5f25-a536-3497286fc6ae', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 9, 9, 'Help us, God of our salvation, for the glory of your name. Deliver us, and forgive our sins, for your name''s sake.'),
  ('cfc6d8a5-ce08-53ac-a781-8beff456b855', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 10, 10, 'Why should the nations say, "Where is their God?" Let it be known among the nations, before our eyes, that vengeance for your servants'' blood is being poured out.'),
  ('87a2b93b-c0f0-5821-aef9-323f78fbf05a', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 11, 11, 'Let the sighing of the prisoner come before you. According to the greatness of your power, preserve those who are sentenced to death.'),
  ('c39e90f9-6f8b-5725-ab87-771a532530ed', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 12, 12, 'Pay back to our neighbors seven times into their bosom their reproach with which they have reproached you, Lord.'),
  ('b586cdf1-87cd-5e08-ae63-448292e96ab8', 'b716f52c-bce0-587c-a5d7-da32bf3e0b81', NULL, 13, 13, 'So we, your people and sheep of your pasture, will give you thanks forever. We will praise you forever, to all generations. For the Chief Musician. To the tune of "The Lilies of the Covenant." A Psalm by Asaph.'),
  ('aca2d850-8f5e-537c-abe2-e4e2322905eb', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 1, 1, 'Hear us, Shepherd of Israel, you who lead Joseph like a flock, you who sit above the cherubim, shine forth.'),
  ('9c6462ba-b7cd-59f9-a757-cfa0c6754d44', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 2, 2, 'Before Ephraim and Benjamin and Manasseh, stir up your might! Come to save us!'),
  ('9debe339-8a42-5738-a57b-d430256b598b', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 3, 3, 'Turn us again, God. Cause your face to shine, and we will be saved.'),
  ('97168427-ecc6-581d-ab33-a67ade8495f7', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 4, 4, 'Yahweh God of Armies, How long will you be angry against the prayer of your people?'),
  ('6a623090-d90a-5305-a2b7-d659d1093566', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 5, 5, 'You have fed them with the bread of tears, and given them tears to drink in large measure.'),
  ('a438f8a1-b1e9-5614-adc8-ae19153b046e', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 6, 6, 'You make us a source of contention to our neighbors. Our enemies laugh among themselves.'),
  ('0b9016b2-8610-5b84-ab16-8a33ca3f2e52', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 7, 7, 'Turn us again, God of Armies. Cause your face to shine, and we will be saved.'),
  ('b9316f70-f49f-54b5-a344-cdc0a143fd3e', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 8, 8, 'You brought a vine out of Egypt. You drove out the nations, and planted it.'),
  ('41593487-080a-5d72-a81f-176385eaaea0', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 9, 9, 'You cleared the ground for it. It took deep root, and filled the land.'),
  ('e12d48d0-286b-5ac9-aa1d-9f673b9e4456', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 10, 10, 'The mountains were covered with its shadow. Its boughs were like God''s cedars.'),
  ('ecbcf910-8bb7-5379-a95d-bfbed6f5e1ed', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 11, 11, 'It sent out its branches to the sea, Its shoots to the River.'),
  ('9b9ecd62-5f75-5084-a30f-cd936ccfd4ef', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 12, 12, 'Why have you broken down its walls, so that all those who pass by the way pluck it?'),
  ('86ac4133-6e26-541c-ac49-52f9943d08c1', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 13, 13, 'The boar out of the wood ravages it. The wild animals of the field feed on it.'),
  ('4d3e5700-69ef-50f1-a7e0-ba43c6e7d540', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 14, 14, 'Turn again, we beg you, God of Armies. Look down from heaven, and see, and visit this vine,'),
  ('d73685dd-c54e-59f2-a7c8-3f98d63edad3', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 15, 15, 'the stock which your right hand planted, the branch that you made strong for yourself.'),
  ('c023ff89-2987-54bc-aeed-1e4d7a3a85c3', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 16, 16, 'It''s burned with fire. It''s cut down. They perish at your rebuke.'),
  ('fa802b34-8234-5095-a7c9-0c80b7423e40', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 17, 17, 'Let your hand be on the man of your right hand, on the son of man whom you made strong for yourself.'),
  ('acb65af0-68a8-554c-aa91-f8a9e92b39c8', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 18, 18, 'So we will not turn away from you. Revive us, and we will call on your name.'),
  ('28f5cdee-2537-54e8-a277-653622a1e5ae', '0fe8c242-d80e-5114-ace7-c6e9d96fcc45', NULL, 19, 19, 'Turn us again, Yahweh God of Armies. Cause your face to shine, and we will be saved. For the Chief Musician. On an instrument of Gath. By Asaph.'),
  ('890573a6-ca0c-5a42-aef9-6c2160fc05af', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 1, 1, 'Sing aloud to God, our strength! Make a joyful shout to the God of Jacob!'),
  ('3d6bb3cc-3b4e-5078-a034-6f89c0d461f8', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 2, 2, 'Raise a song, and bring here the tambourine, the pleasant lyre with the harp.'),
  ('d32c959f-863b-5527-a808-0bfe556b827f', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 3, 3, 'Blow the trumpet at the New Moon, at the full moon, on our feast day.'),
  ('5728eb0d-0b32-542d-a159-36ba6c1ae350', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 4, 4, 'For it is a statute for Israel, an ordinance of the God of Jacob.'),
  ('9ec68872-eed8-50cb-adc4-403504052dd8', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 5, 5, 'He appointed it in Joseph for a testimony, when he went out over the land of Egypt, I heard a language that I didn''t know.'),
  ('e0017384-1fa2-5607-ac33-8231af788a7d', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 6, 6, '"I removed his shoulder from the burden. His hands were freed from the basket.'),
  ('1a90abb1-9054-5e62-adfe-b0aefc3dbc87', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 7, 7, 'You called in trouble, and I delivered you. I answered you in the secret place of thunder. I tested you at the waters of Meribah." Selah.'),
  ('f066d4a9-f812-5eea-a824-aea57210f3b1', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 8, 8, '"Hear, my people, and I will testify to you, Israel, if you would listen to me!'),
  ('8348a403-4ea8-5048-abfc-2fa52711a52a', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 9, 9, 'There shall be no strange god in you, neither shall you worship any foreign god.'),
  ('04ddc5fd-b472-563f-a588-4ed66b926a3e', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 10, 10, 'I am Yahweh, your God, who brought you up out of the land of Egypt. Open your mouth wide, and I will fill it.'),
  ('7393a40b-3f71-5229-aafb-87a19ef22589', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 11, 11, 'But my people didn''t listen to my voice. Israel desired none of me.'),
  ('c764812b-6156-578f-acfc-78f76172f887', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 12, 12, 'So I let them go after the stubbornness of their hearts, that they might walk in their own counsels.'),
  ('fa248124-3935-52e7-a0ca-d52220e5ded9', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 13, 13, 'Oh that my people would listen to me, that Israel would walk in my ways!'),
  ('287778ba-5108-599a-acc6-5f8c078542d5', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 14, 14, 'I would soon subdue their enemies, and turn my hand against their adversaries.'),
  ('7c882bed-ac2c-5782-a7a1-bbcef759536b', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 15, 15, 'The haters of Yahweh would cringe before him, and their punishment would last forever.'),
  ('ee02ea34-bd54-5afa-abda-88d419350753', '63088c64-b19e-5885-a0e1-b5ac0bb42704', NULL, 16, 16, 'But he would have also fed them with the finest of the wheat. I will satisfy you with honey out of the rock." A Psalm by Asaph.'),
  ('64e75ccc-97e1-5b70-adfc-c9d7bd6d6fd5', 'b1089272-aa4f-5ff8-a46c-e1869919bbd8', NULL, 1, 1, 'God presides in the great assembly. He judges among the gods.'),
  ('8dfb0cb7-4de9-52e7-ab34-346f5a143210', 'b1089272-aa4f-5ff8-a46c-e1869919bbd8', NULL, 2, 2, '"How long will you judge unjustly, and show partiality to the wicked?" Selah.'),
  ('a19e798a-d6d9-54df-affa-38537f20dc68', 'b1089272-aa4f-5ff8-a46c-e1869919bbd8', NULL, 3, 3, '"Defend the weak, the poor, and the fatherless. Maintain the rights of the poor and oppressed.'),
  ('8632c0d1-c4a7-5a45-ae89-b4e677b3ab5c', 'b1089272-aa4f-5ff8-a46c-e1869919bbd8', NULL, 4, 4, 'Rescue the weak and needy. Deliver them out of the hand of the wicked."'),
  ('e00ef2b6-cbab-539d-a9c8-3b8df4d0383b', 'b1089272-aa4f-5ff8-a46c-e1869919bbd8', NULL, 5, 5, 'They don''t know, neither do they understand. They walk back and forth in darkness. All the foundations of the earth are shaken.'),
  ('51ac1c98-62da-5e5e-ae9f-54b87fdc7d37', 'b1089272-aa4f-5ff8-a46c-e1869919bbd8', NULL, 6, 6, 'I said, "You are gods, all of you are sons of the Most High.'),
  ('cd44f457-3c7e-5696-a851-3c8fd3071ee9', 'b1089272-aa4f-5ff8-a46c-e1869919bbd8', NULL, 7, 7, 'Nevertheless you shall die like men, and fall like one of the rulers."'),
  ('a244fa69-f74b-55a2-ad6f-6adf399f9510', 'b1089272-aa4f-5ff8-a46c-e1869919bbd8', NULL, 8, 8, 'Arise, God, judge the earth, for you inherit all of the nations. A song. A Psalm by Asaph.'),
  ('1c097187-823d-5b44-ad0c-86cee9ed9da3', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 1, 1, 'God, don''t keep silent. Don''t keep silent, and don''t be still, God.'),
  ('418ae990-654c-517f-a79c-001e143e8481', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 2, 2, 'For, behold, your enemies are stirred up. Those who hate you have lifted up their heads.'),
  ('e2c69815-b887-5ea4-ae4e-f33d9e39c60b', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 3, 3, 'They conspire with cunning against your people. They plot against your cherished ones.'),
  ('88cfbe58-bc05-5f25-aeb2-1f9b2a6ce132', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 4, 4, '"Come," they say, "and let''s destroy them as a nation, that the name of Israel may be remembered no more."'),
  ('361eed1c-dd44-5864-aadb-ed97a2bda8b9', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 5, 5, 'For they have conspired together with one mind. They form an alliance against you.'),
  ('1059ef7d-b32c-5727-adb6-7a8dfb8f4ca2', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 6, 6, 'The tents of Edom and the Ishmaelites; Moab, and the Hagrites;'),
  ('6d9eee11-fa52-565f-a093-0eec41e58570', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 7, 7, 'Gebal, Ammon, and Amalek; Philistia with the inhabitants of Tyre;'),
  ('ef33a380-86cb-57e6-a60c-bf1f72f40b1a', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 8, 8, 'Assyria also is joined with them. They have helped the children of Lot. Selah.'),
  ('02027e64-82e4-5758-a390-4c49a5b98827', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 9, 9, 'Do to them as you did to Midian, as to Sisera, as to Jabin, at the river Kishon;'),
  ('d8410629-55a3-5f4f-a4ae-f7dd220b3a83', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 10, 10, 'who perished at Endor, who became as dung for the earth.'),
  ('bb566b1d-a8d8-57f9-ae24-b5728a002e9d', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 11, 11, 'Make their nobles like Oreb and Zeeb; yes, all their princes like Zebah and Zalmunna;'),
  ('dd8bc0b1-00ec-5a7c-a4a2-60dde3264428', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 12, 12, 'who said, "Let us take possession of God''s pasturelands."'),
  ('1b0242c4-75b8-5120-ab8d-7ab724f9137e', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 13, 13, 'My God, make them like tumbleweed; like chaff before the wind.'),
  ('f5574aa7-e5c6-5927-a408-e6a54e6c1104', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 14, 14, 'As the fire that burns the forest, as the flame that sets the mountains on fire,'),
  ('5c8dfc34-5b0e-5596-a430-057d1deb1370', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 15, 15, 'so pursue them with your tempest, and terrify them with your storm.'),
  ('74b0a2dd-8d4d-5be0-a69f-e8b41d019ce4', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 16, 16, 'Fill their faces with confusion, that they may seek your name, Yahweh.'),
  ('dd4af3f5-c5e7-5210-ae6b-cfea36e09c7b', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 17, 17, 'Let them be disappointed and dismayed forever. Yes, let them be confounded and perish;'),
  ('6072c540-6dc2-5b02-a32a-ad2ac132a17c', '52ba9714-a81d-5ed5-a77f-26980c4cf69c', NULL, 18, 18, 'that they may know that you alone, whose name is Yahweh, are the Most High over all the earth. For the Chief Musician. On an instrument of Gath. A Psalm by the sons of Korah.'),
  ('860dd27f-a889-50e5-a86b-2457cd88bccf', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 1, 1, 'How lovely are your dwellings, Yahweh of Armies!'),
  ('8b962b67-4927-59cd-ae13-3d313366f153', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 2, 2, 'My soul longs, and even faints for the courts of Yahweh. My heart and my flesh cry out for the living God.'),
  ('97e3c11b-e6e9-5e51-ad16-c147a3f9aef1', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 3, 3, 'Yes, the sparrow has found a home, and the swallow a nest for herself, where she may have her young, near your altars, Yahweh of Armies, my King, and my God.'),
  ('7500dca0-ecc0-5240-a5b6-8605838aa799', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 4, 4, 'Blessed are those who dwell in your house. They are always praising you. Selah.'),
  ('c252047e-a309-52a6-a66e-3785cf37fdf8', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 5, 5, 'Blessed are those whose strength is in you; who have set their hearts on a pilgrimage.'),
  ('0ff04b5f-27bd-5620-a579-22f3c7f878a1', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 6, 6, 'Passing through the valley of Weeping, they make it a place of springs. Yes, the autumn rain covers it with blessings.'),
  ('7c5594d0-05f9-5bd2-a251-339b1fb092a9', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 7, 7, 'They go from strength to strength. Everyone of them appears before God in Zion.'),
  ('d40b7484-44df-5184-a2cd-dbd3bb918178', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 8, 8, 'Yahweh, God of Armies, hear my prayer. Listen, God of Jacob. Selah.'),
  ('a023cf84-a67b-5a74-a952-99dd66899b34', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 9, 9, 'Behold, God our shield, look at the face of your anointed.'),
  ('d7a32bbe-d9bc-5aae-a32a-95d01fb487b3', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 10, 10, 'For a day in your courts is better than a thousand. I would rather be a doorkeeper in the house of my God, than to dwell in the tents of wickedness.'),
  ('27198ac4-3c7e-5a31-ac21-a0c629714701', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 11, 11, 'For Yahweh God is a sun and a shield. Yahweh will give grace and glory. He withholds no good thing from those who walk blamelessly.'),
  ('5756ad2a-a7f1-5694-aafd-9097a7c318f7', '9bfd27c6-27cf-5a80-a453-64804404079e', NULL, 12, 12, 'Yahweh of Armies, blessed is the man who trusts in you. For the Chief Musician. A Psalm by the sons of Korah.'),
  ('d7dbf9bf-85b4-5e78-a854-6921ea0b772e', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 1, 1, 'Yahweh, you have been favorable to your land. You have restored the fortunes of Jacob.'),
  ('ded218af-3e8c-5a9a-a887-fb70715cf5d0', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 2, 2, 'You have forgiven the iniquity of your people. You have covered all their sin. Selah.'),
  ('2a6dfa7c-b6a7-5aa4-ad0a-1eaeeb67ad59', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 3, 3, 'You have taken away all your wrath. You have turned from the fierceness of your anger.'),
  ('4b5171a3-0817-505b-ab4d-1b9d667b0e89', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 4, 4, 'Turn us, God of our salvation, and cause your indignation toward us to cease.'),
  ('bb4f68c1-8afc-5cc1-a56b-17984b70d40e', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 5, 5, 'Will you be angry with us forever? Will you draw out your anger to all generations?'),
  ('6a6d6824-00db-5eb7-ae4c-dea677dc3ee7', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 6, 6, 'Won''t you revive us again, that your people may rejoice in you?'),
  ('4b2a0f40-76f9-5d75-aa4b-1f842a4fb5b8', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 7, 7, 'Show us your loving kindness, Yahweh. Grant us your salvation.'),
  ('6ac78b45-c45c-508e-a8e0-04cdee21f296', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 8, 8, 'I will hear what God, Yahweh, will speak, for he will speak peace to his people, his saints; but let them not turn again to folly.'),
  ('027e3120-b250-54d8-a20b-c332e8a3b359', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 9, 9, 'Surely his salvation is near those who fear him, that glory may dwell in our land.'),
  ('0a80ce77-6fba-51dd-ab19-76f3d25d81d4', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 10, 10, 'Mercy and truth meet together. Righteousness and peace have kissed each other.'),
  ('0017c39a-2499-5f76-a1ee-f46723eaa932', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 11, 11, 'Truth springs out of the earth. Righteousness has looked down from heaven.'),
  ('e41a4ad1-e611-50d0-af3a-e2cae0376421', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 12, 12, 'Yes, Yahweh will give that which is good. Our land will yield its increase.'),
  ('e4bfb49f-b178-592c-a762-57b81424378e', '5eb9e4aa-e28f-5785-adec-569c7f95e07a', NULL, 13, 13, 'Righteousness goes before him, And prepares the way for his steps. A Prayer by David.'),
  ('e7894007-6f20-5776-a464-7dcdaee31f6f', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 1, 1, 'Hear, Yahweh, and answer me, for I am poor and needy.'),
  ('434351c9-a453-5c9b-ad6a-36f9f8fcf65d', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 2, 2, 'Preserve my soul, for I am godly. You, my God, save your servant who trusts in you.'),
  ('ffec6bf8-3a69-5fac-aa87-c39a2eeb2f8e', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 3, 3, 'Be merciful to me, Lord, for I call to you all day long.'),
  ('70ce822b-3f79-5351-a90f-88291a046673', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 4, 4, 'Bring joy to the soul of your servant, for to you, Lord, do I lift up my soul.'),
  ('77a0cab9-4506-50ef-a92f-646e1942de1d', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 5, 5, 'For you, Lord, are good, and ready to forgive; abundant in loving kindness to all those who call on you.'),
  ('a242c8d5-0bda-559f-a1ae-1f390d1c1818', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 6, 6, 'Hear, Yahweh, my prayer. Listen to the voice of my petitions.'),
  ('46279ab6-08d7-5442-a129-86f79c9c5deb', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 7, 7, 'In the day of my trouble I will call on you, for you will answer me.'),
  ('cf9ee5a3-0d42-526a-a35d-1aa220ff478f', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 8, 8, 'There is no one like you among the gods, Lord, nor any deeds like your deeds.'),
  ('48df768c-3e60-5c4c-adb8-b67201e7e502', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 9, 9, 'All nations you have made will come and worship before you, Lord. They shall glorify your name.'),
  ('f897b354-2fdc-5a0b-a5c2-add6d30c584a', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 10, 10, 'For you are great, and do wondrous things. You are God alone.'),
  ('59ea9268-8395-5a2b-a2f1-48adb62597b0', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 11, 11, 'Teach me your way, Yahweh. I will walk in your truth. Make my heart undivided to fear your name.'),
  ('ab2e32af-2439-586a-a483-201254c2b5b4', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 12, 12, 'I will praise you, Lord my God, with my whole heart. I will glorify your name forevermore.'),
  ('e2cdb45b-153c-56ec-ad4b-b027d663ae77', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 13, 13, 'For your loving kindness is great toward me. You have delivered my soul from the lowest Sheol.'),
  ('ff1ae75c-8a7e-54db-a8a4-9751ea66e369', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 14, 14, 'God, the proud have risen up against me. A company of violent men have sought after my soul, and they don''t hold regard for you before them.'),
  ('fb716bd3-0eb7-5c77-a58b-6b41bdf8b734', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 15, 15, 'But you, Lord, are a merciful and gracious God, slow to anger, and abundant in loving kindness and truth.'),
  ('8505510c-634b-5a4b-af8c-bcd57661d042', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 16, 16, 'Turn to me, and have mercy on me! Give your strength to your servant. Save the son of your handmaid.'),
  ('54517585-3e5c-514b-ac21-8f955ab945bf', 'a769e59b-90f7-5af0-a7ed-2df76cb66854', NULL, 17, 17, 'Show me a sign of your goodness, that those who hate me may see it, and be shamed, because you, Yahweh, have helped me, and comforted me. A Psalm by the sons of Korah; a Song.'),
  ('9ea4a421-e7b9-589c-ac5c-2462a2583348', '0dae2b63-9589-5da0-a16c-699921562717', NULL, 1, 1, 'His foundation is in the holy mountains.'),
  ('67ed3d4b-05b9-5440-a5c9-743b5a8f0b00', '0dae2b63-9589-5da0-a16c-699921562717', NULL, 2, 2, 'Yahweh loves the gates of Zion more than all the dwellings of Jacob.'),
  ('a08bb0b1-54bc-5705-a75c-0ac85b22331f', '0dae2b63-9589-5da0-a16c-699921562717', NULL, 3, 3, 'Glorious things are spoken about you, city of God. Selah.'),
  ('e1957693-7336-5ed7-a655-901d20af030b', '0dae2b63-9589-5da0-a16c-699921562717', NULL, 4, 4, 'I will record Rahab and Babylon among those who acknowledge me. Behold, Philistia, Tyre, and also Ethiopia: "This one was born there."'),
  ('8e1e6cd2-040d-5e2e-a2b2-0400a999f06a', '0dae2b63-9589-5da0-a16c-699921562717', NULL, 5, 5, 'Yes, of Zion it will be said, "This one and that one was born in her;" the Most High himself will establish her.'),
  ('086f5e3d-1519-59c3-a5a5-568b86f4a770', '0dae2b63-9589-5da0-a16c-699921562717', NULL, 6, 6, 'Yahweh will count, when he writes up the peoples, "This one was born there." Selah.'),
  ('9b3baf3e-0478-5b95-a27b-d688ac8d73c0', '0dae2b63-9589-5da0-a16c-699921562717', NULL, 7, 7, 'Those who sing as well as those who dance say, "All my springs are in you." A Song. A Psalm by the sons of Korah. For the Chief Musician. To the tune of "The Suffering of Affliction." A contemplation by Heman, the Ezrahite.'),
  ('27795633-8f6e-5ed8-aac0-a4b6e57fb667', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 1, 1, 'Yahweh, the God of my salvation, I have cried day and night before you.'),
  ('d6b942dc-83ef-5d44-ab60-1b1b81d7ebce', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 2, 2, 'Let my prayer enter into your presence. Turn your ear to my cry.'),
  ('fb0a00f8-13b7-5b7c-ade2-695f649a1480', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 3, 3, 'For my soul is full of troubles. My life draws near to Sheol.'),
  ('8b3ba57a-c88d-5499-aebe-ac2edb57e514', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 4, 4, 'I am counted among those who go down into the pit. I am like a man who has no help,'),
  ('7f1ab67e-53de-5665-a475-21f25e42c53b', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 5, 5, 'set apart among the dead, like the slain who lie in the grave, whom you remember no more. They are cut off from your hand.'),
  ('841a9961-637a-50db-a3d6-c98b3f9f4b88', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 6, 6, 'You have laid me in the lowest pit, in the darkest depths.'),
  ('c33ead70-877f-5a90-a6b1-dc276fbb9d66', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 7, 7, 'Your wrath lies heavily on me. You have afflicted me with all your waves. Selah.'),
  ('1ac50d42-1d04-53b7-a1fd-1809a63fb079', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 8, 8, 'You have taken my friends from me. You have made me an abomination to them. I am confined, and I can''t escape.'),
  ('c4e7a056-ab51-58dd-ace9-e00abd1f5944', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 9, 9, 'My eyes are dim from grief. I have called on you daily, Yahweh. I have spread out my hands to you.'),
  ('bc1792c4-6e6f-5887-a1aa-cc502135019d', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 10, 10, 'Do you show wonders to the dead? Do the dead rise up and praise you? Selah.'),
  ('2f3d49d5-413e-5cb0-af73-ed015de4a962', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 11, 11, 'Is your loving kindness declared in the grave? Or your faithfulness in Destruction?'),
  ('1b5b31fc-7ea4-5824-a647-9fb0c503bf86', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 12, 12, 'Are your wonders made known in the dark? Or your righteousness in the land of forgetfulness?'),
  ('d2cbdbf0-5704-57f7-a506-3e946a88ef93', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 13, 13, 'But to you, Yahweh, I have cried. In the morning, my prayer comes before you.'),
  ('dcac71f5-8b01-5699-ac39-6d5570d1a28e', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 14, 14, 'Yahweh, why do you reject my soul? Why do you hide your face from me?'),
  ('402d9ae2-db3a-5e9b-a222-50d8c7102bd7', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 15, 15, 'I am afflicted and ready to die from my youth up. While I suffer your terrors, I am distracted.'),
  ('c8e6497c-a8aa-50fb-abac-7cc700d0ce78', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 16, 16, 'Your fierce wrath has gone over me. Your terrors have cut me off.'),
  ('403d7e94-8fe3-5a30-a6c3-11bd7cb98260', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 17, 17, 'They came around me like water all day long. They completely engulfed me.'),
  ('c01d8581-41f7-5a1e-a182-193482996231', 'ac18ba75-fa99-5457-a9ba-82c9819d40ca', NULL, 18, 18, 'You have put lover and friend far from me, and my friends into darkness. A contemplation by Ethan, the Ezrahite.'),
  ('3c0668ab-1e01-5e63-aaac-b0b2a96c06e1', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 1, 1, 'I will sing of the loving kindness of Yahweh forever. With my mouth, I will make known your faithfulness to all generations.'),
  ('949f5fa7-81f2-5c5a-adfe-f863bffadc94', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 2, 2, 'I indeed declare, "Love stands firm forever. You established the heavens. Your faithfulness is in them."'),
  ('67fbe7e8-d888-5d32-a205-f13e40456c38', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 3, 3, '"I have made a covenant with my chosen one, I have sworn to David, my servant,'),
  ('bcd1479c-fb5a-57f2-aa18-f44a500d98c9', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 4, 4, '''I will establish your seed forever, and build up your throne to all generations.''" Selah.'),
  ('6d9f6232-fd69-59b6-ad72-58188364da4b', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 5, 5, 'The heavens will praise your wonders, Yahweh; your faithfulness also in the assembly of the holy ones.'),
  ('8c36699c-5b4f-5649-a0fc-256487b4f2a9', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 6, 6, 'For who in the skies can be compared to Yahweh? Who among the sons of the heavenly beings is like Yahweh,'),
  ('a7deafbe-d7f8-5762-a708-abb336ad96e1', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 7, 7, 'a very awesome God in the council of the holy ones, to be feared above all those who are around him?'),
  ('8828dc05-e67c-5d13-a3ce-84f7975bfd10', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 8, 8, 'Yahweh, God of Armies, who is a mighty one, like you? Yah, your faithfulness is around you.'),
  ('36f8bf2e-0e00-5ee3-ad3e-6d63d55858a7', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 9, 9, 'You rule the pride of the sea. When its waves rise up, you calm them.'),
  ('359c042c-dc2f-5395-ae84-4796ab377e0c', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 10, 10, 'You have broken Rahab in pieces, like one of the slain. You have scattered your enemies with your mighty arm.'),
  ('e3e1dff1-ab37-5fd8-a388-8f32e8dcf581', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 11, 11, 'The heavens are yours. The earth also is yours; the world and its fullness. You have founded them.'),
  ('bbb9c42a-db98-598b-a317-a10848a9e0a6', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 12, 12, 'The north and the south, you have created them. Tabor and Hermon rejoice in your name.'),
  ('ded44386-139a-5fb7-a9f6-165d55887ef2', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 13, 13, 'You have a mighty arm. Your hand is strong, and your right hand is exalted.'),
  ('61da250d-c40b-5152-abe0-b01de3a85aa6', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 14, 14, 'Righteousness and justice are the foundation of your throne. Loving kindness and truth go before your face.'),
  ('837f1773-7f9b-531c-a6ff-477634e1bdc7', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 15, 15, 'Blessed are the people who learn to acclaim you. They walk in the light of your presence, Yahweh.'),
  ('f61f7d00-b4ac-53e5-ae8f-618b9627b4f0', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 16, 16, 'In your name they rejoice all day. In your righteousness, they are exalted.'),
  ('7411cee6-9081-5386-aac1-c1eff889d46b', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 17, 17, 'For you are the glory of their strength. In your favor, our horn will be exalted.'),
  ('edfd4fb9-ebd4-5b5e-ae5a-08dea3902714', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 18, 18, 'For our shield belongs to Yahweh; our king to the Holy One of Israel.'),
  ('75cc421c-2642-5fc6-a2d0-a39dcf812740', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 19, 19, 'Then you spoke in vision to your saints, and said, "I have bestowed strength on the warrior. I have exalted a young man from the people.'),
  ('f65b586c-7345-5ce3-ac9f-bc773beecd2e', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 20, 20, 'I have found David, my servant. I have anointed him with my holy oil,'),
  ('8f661c37-9130-5a5d-a2ad-aa61f41c1761', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 21, 21, 'with whom my hand shall be established. My arm will also strengthen him.'),
  ('36cd1016-7ae7-5fcb-aa3b-d715c8f3e6d7', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 22, 22, 'No enemy will tax him. No wicked man will oppress him.'),
  ('53f92ee3-d4a1-5d37-ab8c-545515de01da', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 23, 23, 'I will beat down his adversaries before him, and strike those who hate him.'),
  ('1d13f661-57d2-53b5-ab1f-27aa9d0a7c61', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 24, 24, 'But my faithfulness and my loving kindness will be with him. In my name, his horn will be exalted.'),
  ('79ae4d17-a3e9-5afd-ab47-7f898f8d1adf', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 25, 25, 'I will set his hand also on the sea, and his right hand on the rivers.'),
  ('07d30e2f-25f4-5e29-aa6c-532ece0bca77', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 26, 26, 'He will call to me, ''You are my Father, my God, and the rock of my salvation!'''),
  ('950ed6a6-6551-5a23-abce-c5fa3f9ffa06', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 27, 27, 'I will also appoint him my firstborn, the highest of the kings of the earth.'),
  ('1cba1782-1025-5e1b-a436-4a2c0c31c59f', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 28, 28, 'I will keep my loving kindness for him forevermore. My covenant will stand firm with him.'),
  ('75fb6d62-edb6-507d-a33d-e7c04d17ac37', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 29, 29, 'I will also make his seed endure forever, and his throne as the days of heaven.'),
  ('f7b35872-43a3-5b49-adf7-7f5b9f4e2e08', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 30, 30, 'If his children forsake my law, and don''t walk in my ordinances;'),
  ('18423112-6d6c-555c-a158-c35bf48ce0c1', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 31, 31, 'if they break my statutes, and don''t keep my commandments;'),
  ('c2dd96c0-f521-55b3-a552-a275e82aeb6e', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 32, 32, 'then I will punish their sin with the rod, and their iniquity with stripes.'),
  ('dcc29832-ebb1-56fa-a984-e1ea9f998145', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 33, 33, 'But I will not completely take my loving kindness from him, nor allow my faithfulness to fail.'),
  ('e913bebe-55ee-501f-a026-ec9bee17e987', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 34, 34, 'I will not break my covenant, nor alter what my lips have uttered.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f54ba6e1-1a9b-5f2e-ae3c-9d1f18753313', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 35, 35, 'Once have I sworn by my holiness, I will not lie to David.'),
  ('4cffaddf-e47e-5dae-a4ed-09cd6de0a0a8', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 36, 36, 'His seed will endure forever, his throne like the sun before me.'),
  ('fca83589-2c24-555e-a7d2-e8e6983e7b0c', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 37, 37, 'It will be established forever like the moon, the faithful witness in the sky." Selah.'),
  ('15f6db24-1e82-5ad8-ab0f-2f8c83354ddc', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 38, 38, 'But you have rejected and spurned. You have been angry with your anointed.'),
  ('315dba54-0e76-54a8-a315-cb539a1f4a67', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 39, 39, 'You have renounced the covenant of your servant. You have defiled his crown in the dust.'),
  ('c6512428-0ad1-5cdc-ae84-e8aba3e968e8', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 40, 40, 'You have broken down all his hedges. You have brought his strongholds to ruin.'),
  ('e8d9c4fb-a96c-53cb-ad9e-d5c6f4d96703', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 41, 41, 'All who pass by the way rob him. He has become a reproach to his neighbors.'),
  ('c893c0bc-602f-56a6-a1c4-8db133a77f34', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 42, 42, 'You have exalted the right hand of his adversaries. You have made all of his enemies rejoice.'),
  ('a1b9dce9-e1dc-5583-a668-df7d864661fe', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 43, 43, 'Yes, you turn back the edge of his sword, and haven''t supported him in battle.'),
  ('00b1d118-5406-5cf2-a25f-143e5549229f', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 44, 44, 'You have ended his splendor, and thrown his throne down to the ground.'),
  ('18045e40-99cf-5663-aaad-96f478517c6c', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 45, 45, 'You have shortened the days of his youth. You have covered him with shame. Selah.'),
  ('f9766f6e-9f34-592b-a635-ae838de33fb0', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 46, 46, 'How long, Yahweh? Will you hide yourself forever? Will your wrath burn like fire?'),
  ('79f5a528-4193-5b32-abfe-43f96f2f3fdd', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 47, 47, 'Remember how short my time is! For what vanity have you created all the children of men!'),
  ('f917c3e6-4831-517a-a274-bc11ecd713a1', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 48, 48, 'What man is he who shall live and not see death, who shall deliver his soul from the power of Sheol? Selah.'),
  ('13f49c4e-d9cf-59f2-a29f-7933f3e218a0', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 49, 49, 'Lord, where are your former loving kindnesses, which you swore to David in your faithfulness?'),
  ('009e4f37-e88e-52a6-aa74-acb11f682c60', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 50, 50, 'Remember, Lord, the reproach of your servants, how I bear in my heart the taunts of all the mighty peoples,'),
  ('e3135ae1-173c-5d3f-a2eb-527a50466cb1', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 51, 51, 'With which your enemies have mocked, Yahweh, with which they have mocked the footsteps of your anointed one.'),
  ('f3120856-eda1-5dc6-ab0b-7f1e5a5e600e', '8a8b58cc-0503-55eb-ad31-f23b3529bcca', NULL, 52, 52, 'Blessed be Yahweh forevermore. Amen, and Amen. BOOK IV A Prayer by Moses, the man of God.'),
  ('d0f03791-fad2-5971-a11b-24a69740584c', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 1, 1, 'Lord, you have been our dwelling place for all generations.'),
  ('c13764c1-22f7-5236-a65f-3aabe8a16fb4', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 2, 2, 'Before the mountains were brought forth, before you had formed the earth and the world, even from everlasting to everlasting, you are God.'),
  ('2fbf3865-1b1a-5a28-a22e-c0159820e902', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 3, 3, 'You turn man to destruction, saying, "Return, you children of men."'),
  ('121e901d-274c-5c72-ae54-1ac93a5393aa', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 4, 4, 'For a thousand years in your sight are just like yesterday when it is past, like a watch in the night.'),
  ('418ca778-4a22-58a1-a94c-ef14bb6b11e1', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 5, 5, 'You sweep them away as they sleep. In the morning they sprout like new grass.'),
  ('85c035c6-135d-533f-a38d-48fa5cfec56d', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 6, 6, 'In the morning it sprouts and springs up. By evening, it is withered and dry.'),
  ('6d275c52-a8c1-5e04-a22a-86cef7adec4c', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 7, 7, 'For we are consumed in your anger. We are troubled in your wrath.'),
  ('fd64a9a8-31bd-529b-adae-9b28550b8c17', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 8, 8, 'You have set our iniquities before you, our secret sins in the light of your presence.'),
  ('8cb80a20-71ab-501d-adde-1783c8dc7d7b', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 9, 9, 'For all our days have passed away in your wrath. We bring our years to an end as a sigh.'),
  ('635eed52-3575-5e7b-a1ad-78f11b333490', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 10, 10, 'The days of our years are seventy, or even by reason of strength eighty years; yet their pride is but labor and sorrow, for it passes quickly, and we fly away.'),
  ('e6f7468a-a300-5755-a1be-dbcf1620fbd2', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 11, 11, 'Who knows the power of your anger, your wrath according to the fear that is due to you?'),
  ('634e0cc9-c06f-51cd-ac4e-1c4eb29c38d1', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 12, 12, 'So teach us to number our days, that we may gain a heart of wisdom.'),
  ('7550c505-a2c9-5e88-a275-abe5e1a17515', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 13, 13, 'Relent, Yahweh! How long? Have compassion on your servants!'),
  ('37a25d9d-42c3-593c-a826-7ee058a76eb5', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 14, 14, 'Satisfy us in the morning with your loving kindness, that we may rejoice and be glad all our days.'),
  ('fca3956d-d63e-5eca-a7c8-f7426665697e', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 15, 15, 'Make us glad for as many days as you have afflicted us, for as many years as we have seen evil.'),
  ('dd4def5d-b281-50f7-aad2-847a45100d4d', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 16, 16, 'Let your work appear to your servants; your glory to their children.'),
  ('ece1349e-74f5-55b5-aba9-65e72aa31778', '733dbe58-0dfe-59c0-a587-cf705e8d7fa2', NULL, 17, 17, 'Let the favor of the Lord our God be on us; establish the work of our hands for us; yes, establish the work of our hands.'),
  ('f9d0c0d5-bc30-5fbb-ab28-db825b142597', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 1, 1, 'He who dwells in the secret place of the Most High will rest in the shadow of the Almighty.'),
  ('5d63f781-4d02-5129-a367-e2dadd5fb242', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 2, 2, 'I will say of Yahweh, "He is my refuge and my fortress; my God, in whom I trust."'),
  ('db804e93-f3d2-5497-a17f-389a95c8d00d', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 3, 3, 'For he will deliver you from the snare of the fowler, and from the deadly pestilence.'),
  ('ec29aa0d-cd27-5ba6-a9c9-8f98c73c67ea', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 4, 4, 'He will cover you with his feathers. Under his wings you will take refuge. His faithfulness is your shield and rampart.'),
  ('bf33d98c-3023-507a-ae59-745e0f8b35d8', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 5, 5, 'You shall not be afraid of the terror by night, nor of the arrow that flies by day;'),
  ('c33c0660-d3a3-5ca9-a4ed-54ea092f2c06', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 6, 6, 'nor of the pestilence that walks in darkness, nor of the destruction that wastes at noonday.'),
  ('cfd4cd40-b617-56fd-af9e-2c1fc285f679', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 7, 7, 'A thousand may fall at your side, and ten thousand at your right hand; but it will not come near you.'),
  ('94899a47-7941-5802-a3fc-461db37fcdfe', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 8, 8, 'You will only look with your eyes, and see the recompense of the wicked.'),
  ('f4cb58d8-997d-5c6e-a2c2-a7a56cf81b4c', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 9, 9, 'Because you have made Yahweh your refuge, and the Most High your dwelling place,'),
  ('117e7dd6-fd95-553c-a2d4-4d62de7b97eb', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 10, 10, 'no evil shall happen to you, neither shall any plague come near your dwelling.'),
  ('ef2c9d78-036c-5b8a-a5b7-453c096a5fcf', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 11, 11, 'For he will put his angels in charge of you, to guard you in all your ways.'),
  ('78fd6166-06c3-53ce-aca7-233269654b63', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 12, 12, 'They will bear you up in their hands, so that you won''t dash your foot against a stone.'),
  ('63a6b445-ea67-5463-af1a-31ea4b12ecac', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 13, 13, 'You will tread on the lion and cobra. You will trample the young lion and the serpent underfoot.'),
  ('e695a15b-c24a-51ce-a0c6-68f0ff5d7904', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 14, 14, '"Because he has set his love on me, therefore I will deliver him. I will set him on high, because he has known my name.'),
  ('ca092273-4ed4-5585-ae2a-ebb1797824d0', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 15, 15, 'He will call on me, and I will answer him. I will be with him in trouble. I will deliver him, and honor him.'),
  ('50780fc4-0707-5f24-af1c-c1d620d13f4c', '51000b1a-a6e7-5667-a62d-94b93eb261db', NULL, 16, 16, 'I will satisfy him with long life, and show him my salvation." A Psalm. A song for the Sabbath day.'),
  ('8c0c5b59-9159-5ecc-a560-02ce199676fb', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 1, 1, 'It is a good thing to give thanks to Yahweh, to sing praises to your name, Most High;'),
  ('cb7cd0e2-5dff-50f7-a7fe-824cad2f22d4', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 2, 2, 'to proclaim your loving kindness in the morning, and your faithfulness every night,'),
  ('6f275b59-f84f-59a1-aa9c-2df9f456190d', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 3, 3, 'with the ten-stringed lute, with the harp, and with the melody of the lyre.'),
  ('3fd17529-eb97-5af8-ad94-903cf2ac1756', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 4, 4, 'For you, Yahweh, have made me glad through your work. I will triumph in the works of your hands.'),
  ('13a4f6a2-494c-533e-a44b-d0aa946f60a3', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 5, 5, 'How great are your works, Yahweh! Your thoughts are very deep.'),
  ('103748bf-21e4-5de3-a3fa-dfc49704418e', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 6, 6, 'A senseless man doesn''t know, neither does a fool understand this:'),
  ('0b442e68-6244-5dd9-aac2-839c7720d084', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 7, 7, 'though the wicked spring up as the grass, and all the evildoers flourish, they will be destroyed forever.'),
  ('8a42e0fa-e0e6-57f3-ac9a-e1bcbab37240', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 8, 8, 'But you, Yahweh, are on high forevermore.'),
  ('0a35f6ec-6335-5d0e-a8b3-cfe1b3c9aa74', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 9, 9, 'For, behold, your enemies, Yahweh, for, behold, your enemies shall perish. All the evildoers will be scattered.'),
  ('37e708cc-d110-5326-a4e1-25a80d3ed4f5', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 10, 10, 'But you have exalted my horn like that of the wild ox. I am anointed with fresh oil.'),
  ('24f2cd58-b0e9-5d9b-a975-7e426ab1f5fd', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 11, 11, 'My eye has also seen my enemies. My ears have heard of the wicked enemies who rise up against me.'),
  ('f5b19130-2deb-5e01-a7be-bfbd6e8a2646', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 12, 12, 'The righteous shall flourish like the palm tree. He will grow like a cedar in Lebanon.'),
  ('d9024569-4ce5-5e3c-a92a-94d66b81451b', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 13, 13, 'They are planted in Yahweh''s house. They will flourish in our God''s courts.'),
  ('c165b89d-5891-5e27-a21e-6c46b18fc6c7', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 14, 14, 'They will still bring forth fruit in old age. They will be full of sap and green,'),
  ('752d8aab-ba53-5b77-a50c-b4c6522f793d', 'f326076b-4e48-56a9-a35a-78fa3d16c98f', NULL, 15, 15, 'to show that Yahweh is upright. He is my rock, and there is no unrighteousness in him.'),
  ('288256f8-2c2a-593e-ab2c-39ced7fe0b5c', 'ff0d7d0e-a821-5a9c-af34-ec31b4b21f22', NULL, 1, 1, 'Yahweh reigns! He is clothed with majesty! Yahweh is armed with strength. The world also is established. It can''t be moved.'),
  ('4e5d84c1-93cf-51fc-acfd-01ae65fb6840', 'ff0d7d0e-a821-5a9c-af34-ec31b4b21f22', NULL, 2, 2, 'Your throne is established from long ago. You are from everlasting.'),
  ('9ec45c64-2195-5809-aa8c-ece97c3ce176', 'ff0d7d0e-a821-5a9c-af34-ec31b4b21f22', NULL, 3, 3, 'The floods have lifted up, Yahweh, the floods have lifted up their voice. The floods lift up their waves.'),
  ('f4e9aa4d-0d4f-55c8-a07b-39641197aab9', 'ff0d7d0e-a821-5a9c-af34-ec31b4b21f22', NULL, 4, 4, 'Above the voices of many waters, the mighty breakers of the sea, Yahweh on high is mighty.'),
  ('784bd553-81e7-5739-a8bd-3cc03f3d2d8a', 'ff0d7d0e-a821-5a9c-af34-ec31b4b21f22', NULL, 5, 5, 'Your statutes stand firm. Holiness adorns your house, Yahweh, forevermore.'),
  ('1aff9588-fbee-57f4-a0e0-8658eb7ecbbc', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 1, 1, 'Yahweh, you God to whom vengeance belongs, you God to whom vengeance belongs, shine forth.'),
  ('a387c807-b572-58a0-a362-a7c9782da16f', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 2, 2, 'Rise up, you judge of the earth. Pay back the proud what they deserve.'),
  ('f569a0fa-4f70-53a3-a91e-e1f2ff91ea62', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 3, 3, 'Yahweh, how long will the wicked, how long will the wicked triumph?'),
  ('27a57d3a-64f0-58af-a4b9-06074d5e5310', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 4, 4, 'They pour out arrogant words. All the evildoers boast.'),
  ('da7cac97-b7d9-534e-a007-dd8e41e3902f', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 5, 5, 'They break your people in pieces, Yahweh, and afflict your heritage.'),
  ('76a8503d-30b0-56f5-ad22-1baa2f13c24d', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 6, 6, 'They kill the widow and the alien, and murder the fatherless.'),
  ('5d8524f0-9897-5810-a88b-5eb2dee69f79', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 7, 7, 'They say, "Yah will not see, neither will Jacob''s God consider."'),
  ('ce2e3a4f-86b4-5f7f-aed4-ac2e6c5e15c9', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 8, 8, 'Consider, you senseless among the people; you fools, when will you be wise?'),
  ('20aeba80-b599-552c-abf0-85ff1681496c', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 9, 9, 'He who implanted the ear, won''t he hear? He who formed the eye, won''t he see?'),
  ('a6df402b-e7ee-5b1b-af4f-164d88acf918', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 10, 10, 'He who disciplines the nations, won''t he punish? He who teaches man knows.'),
  ('d6c27940-759e-5bb9-ad05-879530889ed4', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 11, 11, 'Yahweh knows the thoughts of man, that they are futile.'),
  ('0bfa4d5d-0124-504f-a8fc-43406cecaede', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 12, 12, 'Blessed is the man whom you discipline, Yah, and teach out of your law;'),
  ('6f6b0d44-c771-500c-a539-046640ffae03', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 13, 13, 'that you may give him rest from the days of adversity, until the pit is dug for the wicked.'),
  ('307e5314-77a6-5874-a958-148ad2e04d76', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 14, 14, 'For Yahweh won''t reject his people, neither will he forsake his inheritance.'),
  ('54f5a838-6912-5e41-a161-f6804be1c405', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 15, 15, 'For judgment will return to righteousness. All the upright in heart shall follow it.'),
  ('d797d47e-208f-5d35-a089-dc353171ece8', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 16, 16, 'Who will rise up for me against the wicked? Who will stand up for me against the evildoers?'),
  ('65cd5c21-bab1-5f96-a668-0c1f85e054a2', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 17, 17, 'Unless Yahweh had been my help, my soul would have soon lived in silence.'),
  ('b49533aa-27f2-5fa7-a228-48f38a35ab62', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 18, 18, 'When I said, "My foot is slipping!" Your loving kindness, Yahweh, held me up.'),
  ('79ace103-a1e4-58ad-a3e7-2fbfb6e894b1', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 19, 19, 'In the multitude of my thoughts within me, your comforts delight my soul.'),
  ('b141bd4a-1a1f-549e-a647-4c0818a25aac', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 20, 20, 'Shall the throne of wickedness have fellowship with you, which brings about mischief by statute?'),
  ('66643e06-7b53-5c3a-ac45-0a8ce792df22', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 21, 21, 'They gather themselves together against the soul of the righteous, and condemn the innocent blood.'),
  ('54067a15-e4ce-5d00-abed-534d3ab0bed9', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 22, 22, 'But Yahweh has been my high tower, my God, the rock of my refuge.'),
  ('6b393c6c-acfb-5c9f-a7f5-3ab863456f50', 'a9e9fed2-a28a-5a72-a91b-9cbea881da0e', NULL, 23, 23, 'He has brought on them their own iniquity, and will cut them off in their own wickedness. Yahweh, our God, will cut them off.'),
  ('57769909-7b36-54a3-afcf-5579dae14e1d', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 1, 1, 'Oh come, let''s sing to Yahweh. Let''s shout aloud to the rock of our salvation!'),
  ('19c641ab-6832-5cb5-a7ab-e6cb9a5c56b2', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 2, 2, 'Let''s come before his presence with thanksgiving. Let''s extol him with songs!'),
  ('8fe1b95a-d18d-566b-afc9-66c38586a2c2', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 3, 3, 'For Yahweh is a great God, a great King above all gods.'),
  ('1f6bed41-1bba-5be0-a399-fd9cdcba22ab', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 4, 4, 'In his hand are the deep places of the earth. The heights of the mountains are also his.'),
  ('a3c7b42d-8bf6-5382-a6ff-2b01cca2ba40', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 5, 5, 'The sea is his, and he made it. His hands formed the dry land.'),
  ('10dd10db-80ec-59b5-ab0f-91deac74899b', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 6, 6, 'Oh come, let''s worship and bow down. Let''s kneel before Yahweh, our Maker,'),
  ('5eecf42d-53c4-5038-a1ad-265207380d89', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 7, 7, 'for he is our God. We are the people of his pasture, and the sheep in his care. Today, oh that you would hear his voice!'),
  ('06fa68be-f6be-5239-aead-f3fbb7bd55a7', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 8, 8, 'Don''t harden your heart, as at Meribah, as in the day of Massah in the wilderness,'),
  ('25013c97-ccf6-5103-ab36-fca8efd8c689', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 9, 9, 'when your fathers tempted me, tested me, and saw my work.'),
  ('9b2d7c64-f9cb-531a-aa77-6c318dac8cb9', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 10, 10, 'Forty long years I was grieved with that generation, and said, "It is a people that errs in their heart. They have not known my ways."'),
  ('95193c8c-bdbc-50ce-a19b-8bf0858618b4', 'e00058c3-f6b5-52be-a811-54e77c1ff5fb', NULL, 11, 11, 'Therefore I swore in my wrath, "They won''t enter into my rest."'),
  ('5f371cac-194b-5bf5-a09a-722ca8b7299c', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 1, 1, 'Sing to Yahweh a new song! Sing to Yahweh, all the earth.'),
  ('aac5dde2-97bb-52e5-a5bf-03f2f821d4b9', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 2, 2, 'Sing to Yahweh! Bless his name! Proclaim his salvation from day to day!'),
  ('52b564e0-d25e-5098-a8e7-7eed508c35bd', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 3, 3, 'Declare his glory among the nations, his marvelous works among all the peoples.'),
  ('11ca04ce-321f-51fd-a263-37ea4c3ec0b8', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 4, 4, 'For great is Yahweh, and greatly to be praised! He is to be feared above all gods.'),
  ('a348867c-e93a-5aee-a20f-7558d4fa974e', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 5, 5, 'For all the gods of the peoples are idols, but Yahweh made the heavens.'),
  ('9016754f-9e7d-5244-aec6-b8778819ad09', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 6, 6, 'Honor and majesty are before him. Strength and beauty are in his sanctuary.'),
  ('7d78b9a8-cad7-585d-a2a2-6cdf02f536ad', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 7, 7, 'Ascribe to Yahweh, you families of nations, ascribe to Yahweh glory and strength.'),
  ('a53155c8-3871-5555-ab5c-3522c59386c2', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 8, 8, 'Ascribe to Yahweh the glory due to his name. Bring an offering, and come into his courts.'),
  ('f019b389-45ef-5ef4-abac-44dd12bbd4d1', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 9, 9, 'Worship Yahweh in holy array. Tremble before him, all the earth.'),
  ('908d0762-5165-5756-afd1-f33342c9aafa', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 10, 10, 'Say among the nations, "Yahweh reigns." The world is also established. It can''t be moved. He will judge the peoples with equity.'),
  ('0942f760-aa45-5f27-a7ed-de067ee4b8e7', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 11, 11, 'Let the heavens be glad, and let the earth rejoice. Let the sea roar, and its fullness!'),
  ('f789473e-247d-5994-ab70-42b8645da68f', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 12, 12, 'Let the field and all that is in it exult! Then all the trees of the woods shall sing for joy'),
  ('bac04bbb-f5e8-5a35-afc6-97ac2072b0c8', '46b333a0-943e-5872-a925-b25428ea4e2a', NULL, 13, 13, 'before Yahweh; for he comes, for he comes to judge the earth. He will judge the world with righteousness, the peoples with his truth.'),
  ('03fef0c8-6dee-580b-a1fa-dbc2d89db003', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 1, 1, 'Yahweh reigns! Let the earth rejoice! Let the multitude of islands be glad!'),
  ('4e5c260c-4416-5c14-adc4-5b87ef1da64d', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 2, 2, 'Clouds and darkness are around him. Righteousness and justice are the foundation of his throne.'),
  ('156b6ef4-ac16-59cc-a9bb-6ed60fb28a97', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 3, 3, 'A fire goes before him, and burns up his adversaries on every side.'),
  ('24786907-a751-560c-a780-883ac2a2b826', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 4, 4, 'His lightning lights up the world. The earth sees, and trembles.'),
  ('c4d7efac-afee-5394-a439-b6d3f0669fbf', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 5, 5, 'The mountains melt like wax at the presence of Yahweh, at the presence of the Lord of the whole earth.'),
  ('fc59c55f-8b1f-55f7-a2ea-3f3671a4fa99', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 6, 6, 'The heavens declare his righteousness. All the peoples have seen his glory.'),
  ('def17baa-ba11-5809-a226-fb28f265c40b', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 7, 7, 'Let all them be shamed who serve engraved images, who boast in their idols. Worship him, all you gods!'),
  ('4df5b40c-b8fd-5073-a25d-c64e2028568d', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 8, 8, 'Zion heard and was glad. The daughters of Judah rejoiced, because of your judgments, Yahweh.'),
  ('20e78d15-1f2d-5335-acbe-41b6b1310167', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 9, 9, 'For you, Yahweh, are most high above all the earth. You are exalted far above all gods.'),
  ('ddc85d5e-1cbc-590d-ad56-2ec73674895a', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 10, 10, 'You who love Yahweh, hate evil. He preserves the souls of his saints. He delivers them out of the hand of the wicked.'),
  ('a9619d11-53ad-5302-a79f-84c0daf5914a', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 11, 11, 'Light is sown for the righteous, and gladness for the upright in heart.'),
  ('44abd0c5-fdd5-59e3-ab24-65cd09c8a364', '6595e193-60d5-555c-ab8f-7c95813a34cb', NULL, 12, 12, 'Be glad in Yahweh, you righteous people! Give thanks to his holy Name. A Psalm.'),
  ('0df96af7-4a53-5f62-a1b8-a5ac4fa87bd0', 'a5b1af2b-7031-5b5c-abaf-860fd84fd112', NULL, 1, 1, 'Sing to Yahweh a new song, for he has done marvelous things! His right hand, and his holy arm, have worked salvation for him.'),
  ('a909acaa-47b3-5c36-aa80-c9c0ef578457', 'a5b1af2b-7031-5b5c-abaf-860fd84fd112', NULL, 2, 2, 'Yahweh has made known his salvation. He has openly shown his righteousness in the sight of the nations.'),
  ('32fd8c6d-e599-55a7-a6a0-d27c7b73e603', 'a5b1af2b-7031-5b5c-abaf-860fd84fd112', NULL, 3, 3, 'He has remembered his loving kindness and his faithfulness toward the house of Israel. All the ends of the earth have seen the salvation of our God.'),
  ('af792ecf-a39f-570c-ac13-918c9e21442b', 'a5b1af2b-7031-5b5c-abaf-860fd84fd112', NULL, 4, 4, 'Make a joyful noise to Yahweh, all the earth! Burst out and sing for joy, yes, sing praises!'),
  ('32b5fe55-7fae-56e8-a93d-f4794a85dd16', 'a5b1af2b-7031-5b5c-abaf-860fd84fd112', NULL, 5, 5, 'Sing praises to Yahweh with the harp, with the harp and the voice of melody.'),
  ('9438a033-3bfe-580a-a04f-06533cb89aa9', 'a5b1af2b-7031-5b5c-abaf-860fd84fd112', NULL, 6, 6, 'With trumpets and sound of the ram''s horn, make a joyful noise before the King, Yahweh.'),
  ('adf271be-8951-5407-ae8e-7a5e611f1e45', 'a5b1af2b-7031-5b5c-abaf-860fd84fd112', NULL, 7, 7, 'Let the sea roar with its fullness; the world, and those who dwell therein.'),
  ('baf7ea75-9335-5634-a9c3-fdb00164bb24', 'a5b1af2b-7031-5b5c-abaf-860fd84fd112', NULL, 8, 8, 'Let the rivers clap their hands. Let the mountains sing for joy together.'),
  ('ae444c6b-cfb8-5083-af75-e14e9b71c5e3', 'a5b1af2b-7031-5b5c-abaf-860fd84fd112', NULL, 9, 9, 'Let them sing before Yahweh, for he comes to judge the earth. He will judge the world with righteousness, and the peoples with equity.'),
  ('b2cc744e-701b-5f18-a8c0-9fb9e358827b', '198f48e3-a84b-51a4-aec7-de3a5bd9aed4', NULL, 1, 1, 'Yahweh reigns! Let the peoples tremble. He sits enthroned among the cherubim. Let the earth be moved.'),
  ('2cd60288-28c0-5ee1-a7aa-7c766c0fd760', '198f48e3-a84b-51a4-aec7-de3a5bd9aed4', NULL, 2, 2, 'Yahweh is great in Zion. He is high above all the peoples.'),
  ('55b4afd4-08c3-542d-a313-7b439560dab2', '198f48e3-a84b-51a4-aec7-de3a5bd9aed4', NULL, 3, 3, 'Let them praise your great and awesome name. He is Holy!'),
  ('0d641a00-6bf2-5baa-a892-c0874887e218', '198f48e3-a84b-51a4-aec7-de3a5bd9aed4', NULL, 4, 4, 'The King''s strength also loves justice. You do establish equity. You execute justice and righteousness in Jacob.'),
  ('6ae80ac6-7af6-5b18-a6ec-7beb2ead6230', '198f48e3-a84b-51a4-aec7-de3a5bd9aed4', NULL, 5, 5, 'Exalt Yahweh our God. Worship at his footstool. He is Holy!'),
  ('5b95db69-8578-54b1-adb8-faf5cb9f685f', '198f48e3-a84b-51a4-aec7-de3a5bd9aed4', NULL, 6, 6, 'Moses and Aaron were among his priests, Samuel among those who call on his name; they called on Yahweh, and he answered them.'),
  ('23316697-3c6b-5793-a29d-28435ca056a4', '198f48e3-a84b-51a4-aec7-de3a5bd9aed4', NULL, 7, 7, 'He spoke to them in the pillar of cloud. They kept his testimonies, the statute that he gave them.'),
  ('e00662de-b205-55b9-ac81-e1cee7491e26', '198f48e3-a84b-51a4-aec7-de3a5bd9aed4', NULL, 8, 8, 'You answered them, Yahweh our God. You are a God who forgave them, although you took vengeance for their doings.'),
  ('bf1b9167-880f-506b-ae07-8398a0f6ccd8', '198f48e3-a84b-51a4-aec7-de3a5bd9aed4', NULL, 9, 9, 'Exalt Yahweh, our God. Worship at his holy hill, for Yahweh, our God, is holy! A Psalm of thanksgiving.'),
  ('a9a6ef97-ce43-5e05-a6c3-b660e41aa625', 'a22d6287-66b5-50c6-ad4c-34957b285644', NULL, 1, 1, 'Shout for joy to Yahweh, all you lands!'),
  ('36953801-7e96-55fc-a6f6-c4148740eeaf', 'a22d6287-66b5-50c6-ad4c-34957b285644', NULL, 2, 2, 'Serve Yahweh with gladness. Come before his presence with singing.'),
  ('ab25a586-8c78-536c-ae81-53c1f1165dd5', 'a22d6287-66b5-50c6-ad4c-34957b285644', NULL, 3, 3, 'Know that Yahweh, he is God. It is he who has made us, and we are his. We are his people, and the sheep of his pasture.'),
  ('b9287454-1541-59be-a496-e44e60fbc6a8', 'a22d6287-66b5-50c6-ad4c-34957b285644', NULL, 4, 4, 'Enter into his gates with thanksgiving, into his courts with praise. Give thanks to him, and bless his name.'),
  ('bf548f45-41ec-5cac-ac55-a9febd7bb28a', 'a22d6287-66b5-50c6-ad4c-34957b285644', NULL, 5, 5, 'For Yahweh is good. His loving kindness endures forever, his faithfulness to all generations. A Psalm by David.'),
  ('0b608c74-4b01-542b-a913-41b0b0b2ac38', '22ceec5a-9bed-569c-ac82-bf6108a32c1c', NULL, 1, 1, 'I will sing of loving kindness and justice. To you, Yahweh, I will sing praises.'),
  ('b307cf5c-6523-5726-a602-3c4ca22814f8', '22ceec5a-9bed-569c-ac82-bf6108a32c1c', NULL, 2, 2, 'I will be careful to live a blameless life. When will you come to me? I will walk within my house with a blameless heart.'),
  ('ffc5fb5c-250f-56a6-a8b7-b9a9acd9ef5c', '22ceec5a-9bed-569c-ac82-bf6108a32c1c', NULL, 3, 3, 'I will set no vile thing before my eyes. I hate the deeds of faithless men. They will not cling to me.'),
  ('3298055b-98b2-566a-ac90-8bf41caf16f0', '22ceec5a-9bed-569c-ac82-bf6108a32c1c', NULL, 4, 4, 'A perverse heart will be far from me. I will have nothing to do with evil.'),
  ('86df6241-73e8-58ac-ae54-0829f78b2e1e', '22ceec5a-9bed-569c-ac82-bf6108a32c1c', NULL, 5, 5, 'I will silence whoever secretly slanders his neighbor. I won''t tolerate one who is haughty and conceited.'),
  ('593a174e-dd92-53cd-a287-b63e807bb90e', '22ceec5a-9bed-569c-ac82-bf6108a32c1c', NULL, 6, 6, 'My eyes will be on the faithful of the land, that they may dwell with me. He who walks in a perfect way, he will serve me.'),
  ('f2dfba95-0659-5c4b-aee3-686883f00446', '22ceec5a-9bed-569c-ac82-bf6108a32c1c', NULL, 7, 7, 'He who practices deceit won''t dwell within my house. He who speaks falsehood won''t be established before my eyes.'),
  ('b21aa6cb-1c4f-5dd9-a67a-b0df1bb0d8dd', '22ceec5a-9bed-569c-ac82-bf6108a32c1c', NULL, 8, 8, 'Morning by morning, I will destroy all the wicked of the land; to cut off all the workers of iniquity from Yahweh''s city. A Prayer of the afflicted, when he is overwhelmed and pours out his complaint before Yahweh.'),
  ('c5d52342-ab89-5edd-a619-d9df75044348', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 1, 1, 'Hear my prayer, Yahweh! Let my cry come to you.'),
  ('b4216fa2-aa62-5b53-aca0-90c498de8f55', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 2, 2, 'Don''t hide your face from me in the day of my distress. Turn your ear to me. Answer me quickly in the day when I call.'),
  ('5189d854-3b0d-58b1-a772-312139c8bcde', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 3, 3, 'For my days consume away like smoke. My bones are burned as a torch.'),
  ('fc9a3483-a1bb-5f50-a7cc-4fd91ab31579', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 4, 4, 'My heart is blighted like grass, and withered, for I forget to eat my bread.'),
  ('9e2dc3e7-f9b1-5601-a6d9-722925f6de53', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 5, 5, 'By reason of the voice of my groaning, my bones stick to my skin.'),
  ('1a3fc549-2dcb-555a-a983-8dab34266788', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 6, 6, 'I am like a pelican of the wilderness. I have become as an owl of the waste places.'),
  ('d93d9e59-40df-5fa7-ab4e-d53188c6f860', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 7, 7, 'I watch, and have become like a sparrow that is alone on the housetop.'),
  ('57d2c235-ece3-564c-a5be-ebdd0c7de99e', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 8, 8, 'My enemies reproach me all day. Those who are mad at me use my name as a curse.'),
  ('bc476a75-e2ca-5a9a-ac0e-7cd731ade4e7', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 9, 9, 'For I have eaten ashes like bread, and mixed my drink with tears,'),
  ('af20cc3d-5947-5ddc-a800-8fcae8344a4e', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 10, 10, 'Because of your indignation and your wrath, for you have taken me up, and thrown me away.'),
  ('52e7a421-86fa-5101-aeed-f9b79defc696', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 11, 11, 'My days are like a long shadow. I have withered like grass.'),
  ('44c6357b-f522-5826-abdc-961d67719c08', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 12, 12, 'But you, Yahweh, will remain forever; your renown endures to all generations.'),
  ('fbd0a112-647f-5b9c-a7e4-767704da370d', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 13, 13, 'You will arise and have mercy on Zion; for it is time to have pity on her. Yes, the set time has come.'),
  ('9f7571d2-5a30-535e-a1ac-f0a7de4045c0', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 14, 14, 'For your servants take pleasure in her stones, and have pity on her dust.'),
  ('ad636ffc-f4fd-5ae4-a76f-ab681da9252d', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 15, 15, 'So the nations will fear the name of Yahweh; all the kings of the earth your glory.'),
  ('39928e1e-a777-5954-a182-791f2c15bf9c', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 16, 16, 'For Yahweh has built up Zion. He has appeared in his glory.'),
  ('fa690fef-207a-57c6-aa31-9c8dd93e93e1', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 17, 17, 'He has responded to the prayer of the destitute, and has not despised their prayer.'),
  ('4b8591c7-ca54-5bd0-aea6-934d69aa74aa', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 18, 18, 'This will be written for the generation to come. A people which will be created will praise Yah.'),
  ('f5c147c7-bc81-5640-a923-3a63df296ee6', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 19, 19, 'For he has looked down from the height of his sanctuary. From heaven, Yahweh saw the earth;'),
  ('b3437df9-501c-5f20-a0cc-74690d5b5615', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 20, 20, 'to hear the groans of the prisoner; to free those who are condemned to death;'),
  ('595744b2-88c6-5cfa-a8c4-a4d5c8ca46f1', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 21, 21, 'that men may declare the name of Yahweh in Zion, and his praise in Jerusalem;'),
  ('5e56dccf-8d05-57be-ae53-5a0a406a054d', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 22, 22, 'when the peoples are gathered together, the kingdoms, to serve Yahweh.'),
  ('14fd7279-db5c-50ee-a067-3083693e0baa', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 23, 23, 'He weakened my strength along the course. He shortened my days.'),
  ('b63469c7-1dcf-5628-ab91-903ad99002e9', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 24, 24, 'I said, "My God, don''t take me away in the midst of my days. Your years are throughout all generations.'),
  ('8ceb7bb4-d84b-5b1b-a66e-7df81fc21cec', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 25, 25, 'Of old, you laid the foundation of the earth. The heavens are the work of your hands.'),
  ('422ef1d9-059f-5aa1-a19f-cd16a40018f8', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 26, 26, 'They will perish, but you will endure. Yes, all of them will wear out like a garment. You will change them like a cloak, and they will be changed.'),
  ('9ac2a9c8-72e6-51e2-a91e-0f0db9bd0e0e', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 27, 27, 'But you are the same. Your years will have no end.'),
  ('c285ef3e-2f5f-54cb-ae9f-be3b2b22c1ad', '6599e9fb-bd98-530a-a182-c01734d20bb3', NULL, 28, 28, 'The children of your servants will continue. Their seed will be established before you." By David.'),
  ('584434a3-f319-52f9-a651-09d708b3fdb6', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 1, 1, 'Praise Yahweh, my soul! All that is within me, praise his holy name!'),
  ('d4ec0231-efe3-5fa6-a77a-334a7961d7a0', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 2, 2, 'Praise Yahweh, my soul, and don''t forget all his benefits;'),
  ('3d6fd235-5d7a-5dc7-a8cb-73da46cb7f8e', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 3, 3, 'who forgives all your sins; who heals all your diseases;'),
  ('b594034f-ecc0-5b9f-a267-25a0d4719984', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 4, 4, 'who redeems your life from destruction; who crowns you with loving kindness and tender mercies;'),
  ('7e03eed1-afc7-535c-acd1-9857b0189a10', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 5, 5, 'who satisfies your desire with good things, so that your youth is renewed like the eagle''s.'),
  ('dd04f4da-6fbc-5a4b-a86a-01609fc88ccc', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 6, 6, 'Yahweh executes righteous acts, and justice for all who are oppressed.'),
  ('26472938-44af-5be7-a3ce-97fb1b428bc8', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 7, 7, 'He made known his ways to Moses, his deeds to the children of Israel.'),
  ('fd74ca3a-326e-5cc0-accb-05abd92a63b6', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 8, 8, 'Yahweh is merciful and gracious, slow to anger, and abundant in loving kindness.'),
  ('22945466-161e-5c0e-a361-c065da9513be', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 9, 9, 'He will not always accuse; neither will he stay angry forever.'),
  ('eaa014cf-c94b-5ed0-a30e-9d6604c91ad4', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 10, 10, 'He has not dealt with us according to our sins, nor repaid us for our iniquities.'),
  ('6a62c67c-7b22-5693-a4bf-8a2f7d87434d', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 11, 11, 'For as the heavens are high above the earth, so great is his loving kindness toward those who fear him.'),
  ('cfc7a120-7d3e-5f18-a5bb-4366a2f5d5d3', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 12, 12, 'As far as the east is from the west, so far has he removed our transgressions from us.'),
  ('fac466ee-9561-5dbe-a223-8ba62c14167a', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 13, 13, 'Like a father has compassion on his children, so Yahweh has compassion on those who fear him.'),
  ('a6c92238-0c91-5194-abe3-439ddebc0895', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 14, 14, 'For he knows how we are made. He remembers that we are dust.'),
  ('19aa7854-efc9-56b9-ae84-6d131cb50bfa', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 15, 15, 'As for man, his days are like grass. As a flower of the field, so he flourishes.'),
  ('c2fe99a5-d628-51ce-a049-afa6861bef8f', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 16, 16, 'For the wind passes over it, and it is gone. Its place remembers it no more.'),
  ('1f5e3fb9-df60-5658-ad92-bc7b17c6dbd7', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 17, 17, 'But Yahweh''s loving kindness is from everlasting to everlasting with those who fear him, his righteousness to children''s children;'),
  ('566e9fd0-4fcb-5e9b-aa5c-d13a9713cd24', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 18, 18, 'to those who keep his covenant, to those who remember to obey his precepts.'),
  ('996cc36f-3721-5e4c-afd2-56694da4eb9d', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 19, 19, 'Yahweh has established his throne in the heavens. His kingdom rules over all.'),
  ('7529852e-d3ff-550b-afe1-8b59f64af02a', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 20, 20, 'Praise Yahweh, you angels of his, who are mighty in strength, who fulfill his word, obeying the voice of his word.'),
  ('3b1b9e84-37a3-52ff-aad7-8197ed39fff0', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 21, 21, 'Praise Yahweh, all you armies of his, you servants of his, who do his pleasure.'),
  ('0695a4af-0610-5c80-a9c0-43f225d459dd', 'b65a7655-8d52-5c6f-a563-810bbea67b8e', NULL, 22, 22, 'Praise Yahweh, all you works of his, in all places of his dominion. Praise Yahweh, my soul!'),
  ('070cb685-7ddc-540b-abf9-9b7f6747ef0f', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 1, 1, 'Bless Yahweh, my soul. Yahweh, my God, you are very great. You are clothed with honor and majesty.'),
  ('7bc91b9a-aeca-5ae2-a916-d5dbcc43fed2', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 2, 2, 'He covers himself with light as with a garment. He stretches out the heavens like a curtain.'),
  ('60b983c7-9c2e-5098-ac60-3607883c4a27', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 3, 3, 'He lays the beams of his rooms in the waters. He makes the clouds his chariot. He walks on the wings of the wind.'),
  ('785d1a90-dc2f-51f3-af92-d8324b531c12', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 4, 4, 'He makes his messengers winds; his servants flames of fire.'),
  ('efa02cb9-9a4a-52cc-a13c-24d635a874bc', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 5, 5, 'He laid the foundations of the earth, that it should not be moved forever.'),
  ('082aa1fd-4fd5-53cd-a9e5-30bafd2778b8', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 6, 6, 'You covered it with the deep as with a cloak. The waters stood above the mountains.'),
  ('a925006c-9020-57ea-aec4-5e43efb9bc09', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 7, 7, 'At your rebuke they fled. At the voice of your thunder they hurried away.'),
  ('025d9521-0c54-5c7d-a297-e8004fb64d40', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 8, 8, 'The mountains rose, the valleys sank down, to the place which you had assigned to them.'),
  ('b7209dc1-e4c4-5a2b-a80c-292d60956a03', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 9, 9, 'You have set a boundary that they may not pass over; that they don''t turn again to cover the earth.'),
  ('bf370c78-5d59-5a48-ad4f-70a6b431a1d1', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 10, 10, 'He sends forth springs into the valleys. They run among the mountains.'),
  ('393a8545-4c49-549d-a959-246bc8a94fa4', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 11, 11, 'They give drink to every animal of the field. The wild donkeys quench their thirst.'),
  ('73030fe2-1bc1-5c53-aab3-168fea66bf2a', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 12, 12, 'The birds of the sky nest by them. They sing among the branches.'),
  ('c4b4bfb9-47ee-5c56-a8c1-c22215efcce3', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 13, 13, 'He waters the mountains from his rooms. The earth is filled with the fruit of your works.'),
  ('f3309b94-5e5e-5730-a775-770121c26eee', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 14, 14, 'He causes the grass to grow for the livestock, and plants for man to cultivate, that he may bring forth food out of the earth:'),
  ('428b756b-2a9b-592a-a046-337471e262e0', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 15, 15, 'wine that makes glad the heart of man, oil to make his face to shine, and bread that strengthens man''s heart.'),
  ('c21a0a59-b07a-5eaa-ae5f-7233d1379d23', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 16, 16, 'Yahweh''s trees are well watered, the cedars of Lebanon, which he has planted;'),
  ('0759f7c1-0d0e-5134-ae49-019c02084bf1', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 17, 17, 'where the birds make their nests. The stork makes its home in the fir trees.'),
  ('ff92c04c-2870-5979-a8a6-119d87dd293b', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 18, 18, 'The high mountains are for the wild goats. The rocks are a refuge for the rock badgers.'),
  ('b895f604-7440-5908-a3b0-b176228caba3', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 19, 19, 'He appointed the moon for seasons. The sun knows when to set.'),
  ('3e11cd5d-684f-5c12-aae6-f6e4842753fb', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 20, 20, 'You make darkness, and it is night, in which all the animals of the forest prowl.'),
  ('2a0ff89e-cd8e-50b5-a300-0f6cae5ce04a', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 21, 21, 'The young lions roar after their prey, and seek their food from God.'),
  ('374c9fdf-0360-5e21-a3a9-c5ffcf3416d6', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 22, 22, 'The sun rises, and they steal away, and lay down in their dens.'),
  ('4fe2f4d6-7a38-5cec-a17c-de4dd19b4b1a', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 23, 23, 'Man goes forth to his work, to his labor until the evening.'),
  ('f47da07c-cd95-5137-a55c-c2877f627a50', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 24, 24, 'Yahweh, how many are your works! In wisdom have you made them all. The earth is full of your riches.'),
  ('23c91c54-d87a-5fe9-adbe-3ec926211c55', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 25, 25, 'There is the sea, great and wide, in which are innumerable living things, both small and large animals.'),
  ('9aaf0dd8-4f95-5947-a44d-a454a021e880', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 26, 26, 'There the ships go, and leviathan, whom you formed to play there.'),
  ('e689b6f9-bf5e-5058-ab28-dc4d754328cf', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 27, 27, 'These all wait for you, that you may give them their food in due season.'),
  ('000e62cb-64f3-562a-a248-61bb3e5c8ec3', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 28, 28, 'You give to them; they gather. You open your hand; they are satisfied with good.'),
  ('4be362ec-7ba6-5772-a04f-d2c522c36644', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 29, 29, 'You hide your face: they are troubled; you take away their breath: they die, and return to the dust.'),
  ('1b6e2e59-a469-581b-a84e-48b5e91d2043', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 30, 30, 'You send forth your Spirit: they are created. You renew the face of the ground.'),
  ('db2eb703-c6ab-5e02-a2d2-e084fcfd9b55', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 31, 31, 'Let the glory of Yahweh endure forever. Let Yahweh rejoice in his works.'),
  ('355c3b19-2036-525f-a7a3-d443da9e7408', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 32, 32, 'He looks at the earth, and it trembles. He touches the mountains, and they smoke.'),
  ('8cbfa7c3-52b2-5486-ae87-d807bc4e5be4', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 33, 33, 'I will sing to Yahweh as long as I live. I will sing praise to my God while I have any being.'),
  ('c9443ffd-e1cf-5dc0-a4fc-3dd87a4b91a2', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 34, 34, 'Let your meditation be sweet to him. I will rejoice in Yahweh.'),
  ('af0f60e2-0acb-52a0-ad05-4fe549bb1868', '0828e4e1-69b9-50e4-a774-3fa1ed3dfe1d', NULL, 35, 35, 'Let sinners be consumed out of the earth. Let the wicked be no more. Bless Yahweh, my soul. Praise Yah!'),
  ('1780742a-af18-568c-aff9-120426786b0e', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 1, 1, 'Give thanks to Yahweh! Call on his name! Make his doings known among the peoples.'),
  ('5cf8fb78-f901-5b7b-a540-7e2f6a5e0afc', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 2, 2, 'Sing to him, sing praises to him! Tell of all his marvelous works.'),
  ('17149db8-29f2-554b-acf4-40ac02673c41', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 3, 3, 'Glory in his holy name. Let the heart of those who seek Yahweh rejoice.'),
  ('eb178e4c-212d-50c4-a976-570f96ad0453', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 4, 4, 'Seek Yahweh and his strength. Seek his face forever more.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('bdefb287-9ede-59c0-afe0-5f49ffce3c35', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 5, 5, 'Remember his marvelous works that he has done; his wonders, and the judgments of his mouth,'),
  ('d501a946-908b-526a-afd9-b704585167e0', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 6, 6, 'you seed of Abraham, his servant, you children of Jacob, his chosen ones.'),
  ('b5c24a27-004f-56f4-a3a6-17efac8b8e6b', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 7, 7, 'He is Yahweh, our God. His judgments are in all the earth.'),
  ('a016afa6-3d9c-5f02-a11d-904215735f55', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 8, 8, 'He has remembered his covenant forever, the word which he commanded to a thousand generations,'),
  ('c1a4ceff-7550-5ba0-ac31-82b20d631f0b', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 9, 9, 'the covenant which he made with Abraham, his oath to Isaac,'),
  ('a2b45b65-37f7-5224-acde-5b218610c5ad', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 10, 10, 'and confirmed the same to Jacob for a statute; to Israel for an everlasting covenant,'),
  ('c3c05602-a875-5fbc-a617-08d3b05ce47a', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 11, 11, 'saying, "To you I will give the land of Canaan, the lot of your inheritance;"'),
  ('005ab3c8-d400-57d0-a6eb-531a11ddd210', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 12, 12, 'when they were but a few men in number, yes, very few, and foreigners in it.'),
  ('d5e7e85f-a9fb-5bf9-af5d-273da970736a', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 13, 13, 'They went about from nation to nation, from one kingdom to another people.'),
  ('5fa2fe72-e7ff-5379-a457-01d6a285d3e2', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 14, 14, 'He allowed no one to do them wrong. Yes, he reproved kings for their sakes,'),
  ('9b624d61-ab94-54a3-ab65-f9569ec88cdc', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 15, 15, '"Don''t touch my anointed ones! Do my prophets no harm!"'),
  ('024e8f0d-07cc-54e9-a953-48f18b3872f6', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 16, 16, 'He called for a famine on the land. He destroyed the food supplies.'),
  ('c1c3dbac-64d1-563c-a099-c81fd43c7c98', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 17, 17, 'He sent a man before them. Joseph was sold for a slave.'),
  ('e8c70af2-85df-5177-addb-6d5ac800d4ad', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 18, 18, 'They bruised his feet with shackles. His neck was locked in irons,'),
  ('61248cba-5330-5e83-a8ed-10e3ecce2bb0', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 19, 19, 'until the time that his word happened, and Yahweh''s word proved him true.'),
  ('5dcc8170-0bbd-58f1-af00-340ced1923d3', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 20, 20, 'The king sent and freed him; even the ruler of peoples, and let him go free.'),
  ('6b43fda1-c6eb-5a1d-a6bb-b07651ce8dc5', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 21, 21, 'He made him lord of his house, and ruler of all of his possessions;'),
  ('e4a98884-6215-548c-ab8d-1047296469b1', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 22, 22, 'to discipline his princes at his pleasure, and to teach his elders wisdom.'),
  ('1b0a229d-5a99-5a7e-a8da-451eafeefebb', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 23, 23, 'Israel also came into Egypt. Jacob lived in the land of Ham.'),
  ('79c58996-d3be-5821-a7b6-b9a452b35443', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 24, 24, 'He increased his people greatly, and made them stronger than their adversaries.'),
  ('10120394-d702-53a5-a806-9ee6c00298fe', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 25, 25, 'He turned their heart to hate his people, to conspire against his servants.'),
  ('a818e0db-4e36-5e41-a400-ae06e8e7210e', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 26, 26, 'He sent Moses, his servant, and Aaron, whom he had chosen.'),
  ('f79ab27e-02f8-59a6-a131-689f67465b76', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 27, 27, 'They performed miracles among them, and wonders in the land of Ham.'),
  ('bfe94a82-66e2-5509-a179-5baec4267679', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 28, 28, 'He sent darkness, and made it dark. They didn''t rebel against his words.'),
  ('42f79ee0-4f7c-57da-ab42-962886009c4e', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 29, 29, 'He turned their waters into blood, and killed their fish.'),
  ('aee67caa-a378-560c-ad25-1af5382dd7e7', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 30, 30, 'Their land swarmed with frogs, even in the rooms of their kings.'),
  ('57ace9ce-5be4-5eb7-acb1-fe5f45a1cda3', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 31, 31, 'He spoke, and swarms of flies came, and lice in all their borders.'),
  ('3346b32a-4975-5cb7-a7ba-c6096cd2540a', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 32, 32, 'He gave them hail for rain, with lightning in their land.'),
  ('c12145c4-8bf9-5533-af41-d513f6f3466d', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 33, 33, 'He struck their vines and also their fig trees, and shattered the trees of their country.'),
  ('2d8808d9-0f8f-57f3-a15b-1207be9cff13', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 34, 34, 'He spoke, and the locusts came, and the grasshoppers, without number,'),
  ('2e2beca7-6b0c-5487-aba1-6618c4eaf6f6', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 35, 35, 'ate up every plant in their land; and ate up the fruit of their ground.'),
  ('2fb8f1a9-4837-584c-a8a3-a93cb561aeb5', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 36, 36, 'He struck also all the firstborn in their land, the first fruits of all their manhood.'),
  ('27a662ea-f39f-585a-aec8-cb2ba89c9a59', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 37, 37, 'He brought them forth with silver and gold. There was not one feeble person among his tribes.'),
  ('e49c4761-73d5-5de2-a7b7-68623c2a31e9', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 38, 38, 'Egypt was glad when they departed, for the fear of them had fallen on them.'),
  ('6385029a-7a19-53fb-ab07-f498c3a1ec85', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 39, 39, 'He spread a cloud for a covering, fire to give light in the night.'),
  ('7660b266-1b8a-565a-a3e0-67e301364135', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 40, 40, 'They asked, and he brought quails, and satisfied them with the bread of the sky.'),
  ('53bf659b-97f5-57e3-aa00-9e98278fe689', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 41, 41, 'He opened the rock, and waters gushed out. They ran as a river in the dry places.'),
  ('363e1535-7fdb-5ab5-a350-c6ee026fff76', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 42, 42, 'For he remembered his holy word, and Abraham, his servant.'),
  ('7e10a634-48f2-5efd-add3-833b1f1ed75f', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 43, 43, 'He brought forth his people with joy, his chosen with singing.'),
  ('c202a23a-4eb9-5bb2-a08b-d8e0756f6f7c', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 44, 44, 'He gave them the lands of the nations. They took the labor of the peoples in possession,'),
  ('9ebba671-26ba-5f4e-a0cb-34de095bc583', '2efb806b-6fcc-5cc0-a8ec-b1b0a5ae1031', NULL, 45, 45, 'that they might keep his statutes, and observe his laws. Praise Yah!'),
  ('ce63b780-d00e-5347-aefb-5357c998b443', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 1, 1, 'Praise Yahweh! Give thanks to Yahweh, for he is good, for his loving kindness endures forever.'),
  ('ea70d2e3-644c-5426-a996-9b2cdf3b29e5', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 2, 2, 'Who can utter the mighty acts of Yahweh, or fully declare all his praise?'),
  ('f9da0a80-749c-5ab9-a2c2-c38d1e30462a', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 3, 3, 'Blessed are those who keep justice. Blessed is one who does what is right at all times.'),
  ('24187015-7a89-52d9-aa07-9ede1a16343c', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 4, 4, 'Remember me, Yahweh, with the favor that you show to your people. Visit me with your salvation,'),
  ('9fe6c527-5e88-5829-a9c0-c447766306c4', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 5, 5, 'that I may see the prosperity of your chosen, that I may rejoice in the gladness of your nation, that I may glory with your inheritance.'),
  ('9d25c758-1748-50d9-a6b0-ef4704a27e5d', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 6, 6, 'We have sinned with our fathers. We have committed iniquity. We have done wickedly.'),
  ('c259920b-1a3e-52d7-a104-2ae120cb697a', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 7, 7, 'Our fathers didn''t understand your wonders in Egypt. They didn''t remember the multitude of your loving kindnesses, but were rebellious at the sea, even at the Red Sea.'),
  ('5e27896c-0a9c-5cb2-a7f7-2013b6e39d4d', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 8, 8, 'Nevertheless he saved them for his name''s sake, that he might make his mighty power known.'),
  ('dc7c0a95-a3a3-5114-af16-c345e48f7159', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 9, 9, 'He rebuked the Red Sea also, and it was dried up; so he led them through the depths, as through a desert.'),
  ('dcde16fe-9a15-5832-afb2-12b85575c037', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 10, 10, 'He saved them from the hand of him who hated them, and redeemed them from the hand of the enemy.'),
  ('344196be-dff4-57bd-a9fc-06a524283be2', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 11, 11, 'The waters covered their adversaries. There was not one of them left.'),
  ('b229119e-c389-500e-a1d2-71b6be4f836d', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 12, 12, 'Then they believed his words. They sang his praise.'),
  ('2f0a6793-4a49-50d1-a73e-a560f97b0af1', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 13, 13, 'They soon forgot his works. They didn''t wait for his counsel,'),
  ('b65d0ba2-4df0-57c2-a5dc-0608f5f0edf2', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 14, 14, 'but gave in to craving in the desert, and tested God in the wasteland.'),
  ('2142d25c-d695-5723-ab97-b7dd2e2fdcaf', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 15, 15, 'He gave them their request, but sent leanness into their soul.'),
  ('c7e3d381-acf1-5acc-ad9d-14b68ac54343', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 16, 16, 'They envied Moses also in the camp, and Aaron, Yahweh''s saint.'),
  ('8649da3f-dd97-5e74-a419-84ddb3b220fb', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 17, 17, 'The earth opened and swallowed up Dathan, and covered the company of Abiram.'),
  ('544330df-ba54-5516-abd3-378f86633451', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 18, 18, 'A fire was kindled in their company. The flame burned up the wicked.'),
  ('545b6902-e7b6-5649-a7bf-c32188c26c92', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 19, 19, 'They made a calf in Horeb, and worshiped a molten image.'),
  ('9b0ce62f-8295-5e24-aaad-149cb992b460', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 20, 20, 'Thus they exchanged their glory for an image of a bull that eats grass.'),
  ('eccde59a-6969-5c78-a0fd-40525bbe6611', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 21, 21, 'They forgot God, their Savior, who had done great things in Egypt,'),
  ('ba245cfe-8153-5d77-a34c-d6532a927796', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 22, 22, 'Wondrous works in the land of Ham, and awesome things by the Red Sea.'),
  ('2d2917cc-a3f6-528c-a0ab-ba0c53314f34', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 23, 23, 'Therefore he said that he would destroy them, had Moses, his chosen, not stood before him in the breach, to turn away his wrath, so that he wouldn''t destroy them.'),
  ('25674333-3b1c-5a77-a391-926add9b671c', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 24, 24, 'Yes, they despised the pleasant land. They didn''t believe his word,'),
  ('d3ef60dc-40e2-58a8-aaca-3348b09fde61', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 25, 25, 'but murmured in their tents, and didn''t listen to Yahweh''s voice.'),
  ('c85e7e89-b8fd-5783-a109-54dc9241ac28', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 26, 26, 'Therefore he swore to them that he would overthrow them in the wilderness,'),
  ('014cc152-65eb-5714-afde-3ccdebd35cfe', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 27, 27, 'that he would overthrow their seed among the nations, and scatter them in the lands.'),
  ('850babec-4d6c-559f-aa8c-da576235492c', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 28, 28, 'They joined themselves also to Baal Peor, and ate the sacrifices of the dead.'),
  ('29660eca-2bfb-5a09-a1e8-8e2c1cefe40b', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 29, 29, 'Thus they provoked him to anger with their deeds. The plague broke in on them.'),
  ('8eb44de4-d919-5b8f-a228-223caf630330', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 30, 30, 'Then Phinehas stood up, and executed judgment, so the plague was stopped.'),
  ('1591bc60-0ee0-54cc-aea9-3085b7177a51', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 31, 31, 'That was credited to him for righteousness, for all generations to come.'),
  ('276caca1-0a0d-5ab3-a398-74240070687b', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 32, 32, 'They angered him also at the waters of Meribah, so that Moses was troubled for their sakes;'),
  ('d3ef5512-e698-56e6-aaf4-9acdc6c6315b', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 33, 33, 'because they were rebellious against his spirit, he spoke rashly with his lips.'),
  ('33c02ba8-b7aa-50de-a56a-ae10d5736c1f', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 34, 34, 'They didn''t destroy the peoples, as Yahweh commanded them,'),
  ('5abdaaf4-25d0-50a9-a50a-96360cf49a47', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 35, 35, 'but mixed themselves with the nations, and learned their works.'),
  ('726b6c30-cd10-5dc0-acdd-d899bead2f44', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 36, 36, 'They served their idols, which became a snare to them.'),
  ('bac12874-759a-568a-aa32-1616efc5554b', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 37, 37, 'Yes, they sacrificed their sons and their daughters to demons.'),
  ('8fa3a4aa-c60d-583e-a5f8-cc229761fd11', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 38, 38, 'They shed innocent blood, even the blood of their sons and of their daughters, whom they sacrificed to the idols of Canaan. The land was polluted with blood.'),
  ('9ff2d861-a226-5aab-ac87-464bb42b5640', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 39, 39, 'Thus were they defiled with their works, and prostituted themselves in their deeds.'),
  ('f5d0e8ea-d700-58ad-a96c-4524bc6bf782', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 40, 40, 'Therefore Yahweh burned with anger against his people. He abhorred his inheritance.'),
  ('57c4dbac-a987-5778-ac06-ed79f47ea2d3', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 41, 41, 'He gave them into the hand of the nations. Those who hated them ruled over them.'),
  ('a93dcb57-e42d-5d10-ac82-0cb5ee2c5003', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 42, 42, 'Their enemies also oppressed them. They were brought into subjection under their hand.'),
  ('d80a6021-bba4-5271-acac-71a8a5ba84d9', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 43, 43, 'Many times he delivered them, but they were rebellious in their counsel, and were brought low in their iniquity.'),
  ('6e11cb2d-7e1e-5ef9-aeb4-26e90369e3c5', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 44, 44, 'Nevertheless he regarded their distress, when he heard their cry.'),
  ('7e8bff11-f594-545b-ad24-d949d0c896d1', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 45, 45, 'He remembered for them his covenant, and repented according to the multitude of his loving kindnesses.'),
  ('df16ff4e-b18c-5e8e-ac8f-28f336527861', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 46, 46, 'He made them also to be pitied by all those who carried them captive.'),
  ('d6f50b18-8565-5d52-ae4f-34cf023a24ef', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 47, 47, 'Save us, Yahweh, our God, gather us from among the nations, to give thanks to your holy name, to triumph in your praise!'),
  ('8fdc183b-7758-5663-a27d-e751bdbac5a7', '7f357aa7-c865-5115-ad0b-20ea6e0762d6', NULL, 48, 48, 'Blessed be Yahweh, the God of Israel, from everlasting even to everlasting! Let all the people say, "Amen." Praise Yah! BOOK V'),
  ('59884639-8a38-5e3e-ae36-ba8691d02b60', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 1, 1, 'Give thanks to Yahweh, for he is good, for his loving kindness endures forever.'),
  ('19d2a2e0-dace-5538-aee4-83f9097d6739', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 2, 2, 'Let the redeemed by Yahweh say so, whom he has redeemed from the hand of the adversary,'),
  ('57d7ae10-9192-536c-a3cc-e2bfd7abb30b', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 3, 3, 'And gathered out of the lands, from the east and from the west, from the north and from the south.'),
  ('cf929f06-7fd5-54ee-acb3-d7adece5988b', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 4, 4, 'They wandered in the wilderness in a desert way. They found no city to live in.'),
  ('b720293a-eb30-53df-afc9-bfc119b84f48', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 5, 5, 'Hungry and thirsty, their soul fainted in them.'),
  ('10c6cdca-e3e0-5af2-a4cd-88eb82932bba', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 6, 6, 'Then they cried to Yahweh in their trouble, and he delivered them out of their distresses,'),
  ('2c5d4171-b6d7-5f74-ac1a-e8d06f53836c', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 7, 7, 'he led them also by a straight way, that they might go to a city to live in.'),
  ('2bd7cb35-19cc-5ec5-ae31-6db6e5d0d263', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 8, 8, 'Let them praise Yahweh for his loving kindness, for his wonderful works to the children of men!'),
  ('96ce86ea-23dd-5f98-a330-ab5724ddcd6f', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 9, 9, 'For he satisfies the longing soul. He fills the hungry soul with good.'),
  ('6e85d4f0-e263-5e26-a9f6-29ef1b279b07', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 10, 10, 'Some sat in darkness and in the shadow of death, being bound in affliction and iron,'),
  ('b4265b0e-d35c-5c54-aec2-9bcc75a96c87', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 11, 11, 'because they rebelled against the words of God, and condemned the counsel of the Most High.'),
  ('9913fab1-11b9-5099-aa92-33777acbbb47', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 12, 12, 'Therefore he brought down their heart with labor. They fell down, and there was none to help.'),
  ('ed72283a-3017-5733-a818-4c96d8ed33ff', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 13, 13, 'Then they cried to Yahweh in their trouble, and he saved them out of their distresses.'),
  ('1fb8d291-2618-5135-abba-5f366facd3ec', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 14, 14, 'He brought them out of darkness and the shadow of death, and broke their bonds in sunder.'),
  ('c351e6bb-68c9-5def-a8ef-af780907da64', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 15, 15, 'Let them praise Yahweh for his loving kindness, for his wonderful works to the children of men!'),
  ('6ff4f754-baa5-5ffa-a860-aae7771e7adf', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 16, 16, 'For he has broken the gates of brass, and cut through bars of iron.'),
  ('1b12fa79-c8f5-5f9f-a5e6-fe5317291bde', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 17, 17, 'Fools are afflicted because of their disobedience, and because of their iniquities.'),
  ('6a06bb6b-0af2-5a8c-a1f8-cbb3ea81db97', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 18, 18, 'Their soul abhors all kinds of food. They draw near to the gates of death.'),
  ('ae0cda64-224f-5715-ad35-2c703e2e141c', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 19, 19, 'Then they cry to Yahweh in their trouble, he saves them out of their distresses.'),
  ('848baabb-9d7b-5024-a43c-bdb2a4b1e9a1', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 20, 20, 'He sends his word, and heals them, and delivers them from their graves.'),
  ('31e5679d-4cbe-54d9-a468-53a3a283373f', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 21, 21, 'Let them praise Yahweh for his loving kindness, for his wonderful works to the children of men!'),
  ('1ca2b02f-b5d3-53a1-ad91-59b7e58e8f43', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 22, 22, 'Let them offer the sacrifices of thanksgiving, and declare his works with singing.'),
  ('2ed73394-1661-5cfa-ac75-7ce2fb0f6a82', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 23, 23, 'Those who go down to the sea in ships, who do business in great waters;'),
  ('106a3675-bf09-59af-a127-5c51df20f3d6', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 24, 24, 'These see Yahweh''s works, and his wonders in the deep.'),
  ('d34a2ac8-7164-5a38-a70f-893836962d03', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 25, 25, 'For he commands, and raises the stormy wind, which lifts up its waves.'),
  ('86c5d724-4ed9-560a-a4ab-ad979a164b2b', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 26, 26, 'They mount up to the sky; they go down again to the depths. Their soul melts away because of trouble.'),
  ('8243f5c4-b501-5ce2-a0e9-d65df8326bc4', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 27, 27, 'They reel back and forth, and stagger like a drunken man, and are at their wits'' end.'),
  ('1aaa6ee0-0778-5c2c-aae5-e3b342044068', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 28, 28, 'Then they cry to Yahweh in their trouble, and he brings them out of their distress.'),
  ('309072e5-ceaf-564e-ae57-624e770b5f72', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 29, 29, 'He makes the storm a calm, so that its waves are still.'),
  ('3e0be10a-5e72-5375-a596-ca268b589e1a', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 30, 30, 'Then they are glad because it is calm, so he brings them to their desired haven.'),
  ('c713e331-64d6-5845-a784-1cd4c3bb9c86', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 31, 31, 'Let them praise Yahweh for his loving kindness, for his wonderful works for the children of men!'),
  ('03e34ca3-40c1-598d-a548-fb26d4618cdb', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 32, 32, 'Let them exalt him also in the assembly of the people, and praise him in the seat of the elders.'),
  ('b716a82f-157f-5132-a4dc-5f0345dca2a5', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 33, 33, 'He turns rivers into a desert, water springs into a thirsty ground,'),
  ('23750754-ce98-573d-a85b-3550e2c5f765', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 34, 34, 'and a fruitful land into a salt waste, for the wickedness of those who dwell in it.'),
  ('8b7a07b3-1d14-5d91-a1dd-fd3d4deb1a48', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 35, 35, 'He turns a desert into a pool of water, and a dry land into water springs.'),
  ('16509449-78ce-5593-ab13-82073fc2551b', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 36, 36, 'There he makes the hungry live, that they may prepare a city to live in,'),
  ('4759b953-9b12-58f3-a523-cb6858053d10', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 37, 37, 'sow fields, plant vineyards, and reap the fruits of increase.'),
  ('40bf96e6-d99f-541b-a65f-db0e1aa1f92e', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 38, 38, 'He blesses them also, so that they are multiplied greatly. He doesn''t allow their livestock to decrease.'),
  ('dbe715fb-c8e1-5d3b-af7a-a794d33bd1dd', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 39, 39, 'Again, they are diminished and bowed down through oppression, trouble, and sorrow.'),
  ('cb8b0591-c25e-5406-a476-e172202eb065', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 40, 40, 'He pours contempt on princes, and causes them to wander in a trackless waste.'),
  ('6755de1b-352d-5640-ac3b-f810b4c200e2', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 41, 41, 'Yet he lifts the needy out of their affliction, and increases their families like a flock.'),
  ('c25a2d10-550f-5eb4-ae9e-094b3399046f', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 42, 42, 'The upright will see it, and be glad. All the wicked will shut their mouths.'),
  ('41dffeb7-b895-54f6-a68c-7da08ee651a3', 'd3dbf15e-27bf-5359-a25f-0e33622cd799', NULL, 43, 43, 'Whoever is wise will pay attention to these things. They will consider the loving kindnesses of Yahweh. A Song. A Psalm by David.'),
  ('8452de0c-800b-5743-abff-99af0a8d950f', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 1, 1, 'My heart is steadfast, God. I will sing and I will make music with my soul.'),
  ('96468dfe-379c-55c3-a7fa-4a934d4e7f08', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 2, 2, 'Wake up, harp and lyre! I will wake up the dawn.'),
  ('683f83dd-c2af-54be-a169-a563e5c8ee58', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 3, 3, 'I will give thanks to you, Yahweh, among the nations. I will sing praises to you among the peoples.'),
  ('b764556c-37bf-5dbc-a592-f13ed006fcd0', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 4, 4, 'For your loving kindness is great above the heavens. Your faithfulness reaches to the skies.'),
  ('6eff1440-71ad-5002-abb8-ee4470e67b43', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 5, 5, 'Be exalted, God, above the heavens! Let your glory be over all the earth.'),
  ('fc0d6166-7ca9-5312-ac4e-511dbd1f30ce', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 6, 6, 'That your beloved may be delivered, save with your right hand, and answer us.'),
  ('ee3bd73f-b779-5209-a10b-b1efd5b7904a', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 7, 7, 'God has spoken from his sanctuary: "In triumph, I will divide Shechem, and measure out the valley of Succoth.'),
  ('13ecaded-e6b1-59a9-a593-e0ea1dfc19c5', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 8, 8, 'Gilead is mine. Manasseh is mine. Ephraim also is my helmet. Judah is my scepter.'),
  ('d013748b-7681-5e0b-a285-d933ff6fd842', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 9, 9, 'Moab is my wash pot. I will toss my sandal on Edom. I will shout over Philistia."'),
  ('af7db385-00fa-5d1f-a0a1-b336cb51892a', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 10, 10, 'Who will bring me into the fortified city? Who has led me to Edom?'),
  ('6d21c1e8-25b2-5fb2-a0c4-88c7759fef5f', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 11, 11, 'Haven''t you rejected us, God? You don''t go forth, God, with our armies.'),
  ('5ba48c34-dcd9-5f19-afff-300fd12ab7a0', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 12, 12, 'Give us help against the enemy, for the help of man is vain.'),
  ('74c7445a-c1f8-5d15-a4ce-9fe17db48cce', '2276b3e3-dcea-567b-a2b3-8d48d5cc1ecd', NULL, 13, 13, 'Through God, we will do valiantly. For it is he who will tread down our enemies. For the Chief Musician. A Psalm by David.'),
  ('4f85543b-8c8d-5f2a-a221-121de1107233', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 1, 1, 'God of my praise, don''t remain silent,'),
  ('4e6e8f63-e007-505e-a858-18f9babb7c5c', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 2, 2, 'for they have opened the mouth of the wicked and the mouth of deceit against me. They have spoken to me with a lying tongue.'),
  ('d936969d-d263-5dba-a7c5-e4483dc706a0', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 3, 3, 'They have also surrounded me with words of hatred, and fought against me without a cause.'),
  ('702ac46e-8078-5fbe-a127-c635cfc97097', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 4, 4, 'In return for my love, they are my adversaries; but I am in prayer.'),
  ('1ae8672b-f7f4-5e8a-ad0e-cd34b3b6a285', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 5, 5, 'They have rewarded me evil for good, and hatred for my love.'),
  ('c304046f-5009-5a08-ae90-c43d31d71e25', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 6, 6, 'Set a wicked man over him. Let an adversary stand at his right hand.'),
  ('eaafcf7e-004d-51fc-a555-d718e09413a3', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 7, 7, 'When he is judged, let him come forth guilty. Let his prayer be turned into sin.'),
  ('0463a184-637a-5bca-a382-c80702e07ba7', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 8, 8, 'Let his days be few. Let another take his office.'),
  ('c01f5f86-e7fb-5ada-ab4b-e6ad13ae5ba9', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 9, 9, 'Let his children be fatherless, and his wife a widow.'),
  ('55276046-afc0-5601-ab28-e38b6f3c36eb', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 10, 10, 'Let his children be wandering beggars. Let them be sought from their ruins.'),
  ('66030431-5542-5cc7-a30f-23df727caf0e', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 11, 11, 'Let the creditor seize all that he has. Let strangers plunder the fruit of his labor.'),
  ('c4f3c033-82cb-5034-ac8a-b4a5846a31f7', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 12, 12, 'Let there be none to extend kindness to him, neither let there be any to have pity on his fatherless children.'),
  ('c9c61e05-f06d-5e6d-a37d-a102953745a7', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 13, 13, 'Let his posterity be cut off. In the generation following let their name be blotted out.'),
  ('316069b7-4650-5c31-a342-36d31123a96d', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 14, 14, 'Let the iniquity of his fathers be remembered by Yahweh. Don''t let the sin of his mother be blotted out.'),
  ('1792bead-a853-52ad-a4c5-f6fd6908d6fd', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 15, 15, 'Let them be before Yahweh continually, that he may cut off the memory of them from the earth;'),
  ('5710464e-8560-5ee3-aac0-00da284d6f5a', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 16, 16, 'because he didn''t remember to show kindness, but persecuted the poor and needy man, the broken in heart, to kill them.'),
  ('a3fd6ff6-884c-512d-a5ea-ee73ebf37242', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 17, 17, 'Yes, he loved cursing, and it came to him. He didn''t delight in blessing, and it was far from him.'),
  ('892b1e12-4076-59dc-a558-18a176f2aab7', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 18, 18, 'He clothed himself also with cursing as with his garment. It came into his inward parts like water, like oil into his bones.'),
  ('e90221d8-727e-553d-a266-8470322d9021', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 19, 19, 'Let it be to him as the clothing with which he covers himself, for the belt that is always around him.'),
  ('2cb805af-7d7a-5b51-ae8b-3b49a69f858c', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 20, 20, 'This is the reward of my adversaries from Yahweh, of those who speak evil against my soul.'),
  ('2ed2621d-9e4c-508b-a6c9-56012ea1ef98', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 21, 21, 'But deal with me, Yahweh the Lord, for your name''s sake, because your loving kindness is good, deliver me;'),
  ('8ef6217a-c519-59cf-ac03-6ec164c4770b', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 22, 22, 'for I am poor and needy. My heart is wounded within me.'),
  ('2ec8ad73-8f9f-5aa3-aa31-6f5f354ed92a', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 23, 23, 'I fade away like an evening shadow. I am shaken off like a locust.'),
  ('a074cc86-51cb-5565-a19a-7be77ea55471', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 24, 24, 'My knees are weak through fasting. My body is thin and lacks fat.'),
  ('a13e47c4-28ff-58a7-a2a2-20eb99a4153a', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 25, 25, 'I have also become a reproach to them. When they see me, they shake their head.'),
  ('8c0b3d2e-f94c-57d0-a670-2eeb37face11', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 26, 26, 'Help me, Yahweh, my God. Save me according to your loving kindness;'),
  ('07272b10-2995-5cb2-a008-38d2e2ee9995', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 27, 27, 'that they may know that this is your hand; that you, Yahweh, have done it.'),
  ('55133bfc-6a56-5413-ae6a-3bc7a3f70229', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 28, 28, 'They may curse, but you bless. When they arise, they will be shamed, but your servant shall rejoice.'),
  ('ad3ce72e-aa77-5f5c-a508-02bc67ac64eb', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 29, 29, 'Let my adversaries be clothed with dishonor. Let them cover themselves with their own shame as with a robe.'),
  ('10e74b9f-06ec-53c9-a738-9a75c125b2c7', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 30, 30, 'I will give great thanks to Yahweh with my mouth. Yes, I will praise him among the multitude.'),
  ('4f5e1028-af44-5a38-a543-34cf7a11e195', '3dfd4afa-e92e-5b9e-ae57-7fb9c8c29c5e', NULL, 31, 31, 'For he will stand at the right hand of the needy, to save him from those who judge his soul. A Psalm by David.'),
  ('a3cd8d57-18c5-50e7-ae0e-3657fee87801', '44ee9926-34cf-552f-a941-b90db3b65a07', NULL, 1, 1, 'Yahweh says to my Lord, "Sit at my right hand, until I make your enemies your footstool for your feet."'),
  ('bd5798de-72f3-54db-aa7d-ff39c7e81ae1', '44ee9926-34cf-552f-a941-b90db3b65a07', NULL, 2, 2, 'Yahweh will send forth the rod of your strength out of Zion. Rule in the midst of your enemies.'),
  ('7a53df3e-120e-5d55-a26c-0e6d406697a7', '44ee9926-34cf-552f-a941-b90db3b65a07', NULL, 3, 3, 'Your people offer themselves willingly in the day of your power, in holy array. Out of the womb of the morning, you have the dew of your youth.'),
  ('9ba75a46-9706-52d8-adf6-1119a2b34b74', '44ee9926-34cf-552f-a941-b90db3b65a07', NULL, 4, 4, 'Yahweh has sworn, and will not change his mind: "You are a priest forever in the order of Melchizedek."'),
  ('1ae44404-1062-513b-aa66-b86d8ba6654d', '44ee9926-34cf-552f-a941-b90db3b65a07', NULL, 5, 5, 'The Lord is at your right hand. He will crush kings in the day of his wrath.'),
  ('a9e5fe97-cefc-5400-aa4c-ca7fd85b0beb', '44ee9926-34cf-552f-a941-b90db3b65a07', NULL, 6, 6, 'He will judge among the nations. He will heap up dead bodies. He will crush the ruler of the whole earth.'),
  ('87caef58-ff88-5bc7-afef-b3a958d8485a', '44ee9926-34cf-552f-a941-b90db3b65a07', NULL, 7, 7, 'He will drink of the brook in the way; therefore he will lift up his head.'),
  ('92523aeb-dd93-5885-add7-d78b4c5da9ed', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 1, 1, 'Praise Yah! I will give thanks to Yahweh with my whole heart, in the council of the upright, and in the congregation.'),
  ('20154285-8d2d-59d6-ad80-39ee1aeab7a9', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 2, 2, 'Yahweh''s works are great, pondered by all those who delight in them.'),
  ('8e91606c-283b-50ca-a6a9-0cfcf190a41b', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 3, 3, 'His work is honor and majesty. His righteousness endures forever.'),
  ('6f1ef4e3-86c1-54d7-ac2e-91af6c51da34', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 4, 4, 'He has caused his wonderful works to be remembered. Yahweh is gracious and merciful.'),
  ('b77d4032-09bb-5f75-a7d4-ae3824737463', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 5, 5, 'He has given food to those who fear him. He always remembers his covenant.'),
  ('dc6283c5-5f82-55ab-aeee-0e3cb97c0e27', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 6, 6, 'He has shown his people the power of his works, in giving them the heritage of the nations.'),
  ('89ae93ae-ff0a-5ebf-a348-511d77405d94', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 7, 7, 'The works of his hands are truth and justice. All his precepts are sure.'),
  ('da51c7fa-d5fe-58bd-adbb-930cf56cbad6', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 8, 8, 'They are established forever and ever. They are done in truth and uprightness.'),
  ('9fdca81b-888b-5796-a476-209d7cee753b', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 9, 9, 'He has sent redemption to his people. He has ordained his covenant forever. His name is holy and awesome!'),
  ('c6028753-e291-5072-a1ac-a477148744a7', '99af62d1-abda-53f0-a95f-ad41ff387a23', NULL, 10, 10, 'The fear of Yahweh is the beginning of wisdom. All those who do his work have a good understanding. His praise endures forever!'),
  ('25cb34e6-9f76-5c81-a073-54d679a93b43', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 1, 1, 'Praise Yah! Blessed is the man who fears Yahweh, who delights greatly in his commandments.'),
  ('ad456b19-1b78-500e-a65d-a38fc9935b90', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 2, 2, 'His seed will be mighty in the land. The generation of the upright will be blessed.'),
  ('f2172dc1-396d-584a-af2e-0f83cf6aa3ed', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 3, 3, 'Wealth and riches are in his house. His righteousness endures forever.'),
  ('0e35f6f8-c9c5-54bd-a302-f735d26c7143', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 4, 4, 'Light dawns in the darkness for the upright, gracious, merciful, and righteous.'),
  ('684b84da-260f-5747-ab27-931611b322ad', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 5, 5, 'It is well with the man who deals graciously and lends. He will maintain his cause in judgment.'),
  ('b58baa84-0d97-5a86-adba-d5c456798271', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 6, 6, 'For he will never be shaken. The righteous will be remembered forever.'),
  ('2a3b0357-d0c7-5cac-a75c-921a9319cc18', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 7, 7, 'He will not be afraid of evil news. His heart is steadfast, trusting in Yahweh.'),
  ('1f1e52ec-5201-5a69-a5d8-a86fef5a9c49', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 8, 8, 'His heart is established. He will not be afraid in the end when he sees his adversaries.'),
  ('30441c84-a3d2-5d4e-a7af-5ec094ba7791', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 9, 9, 'He has dispersed, he has given to the poor. His righteousness endures forever. His horn will be exalted with honor.'),
  ('d86525f7-bce9-5b46-a3ed-2e144e230ee1', '5af599bc-3947-5ee0-a013-09df0a793d53', NULL, 10, 10, 'The wicked will see it, and be grieved. He shall gnash with his teeth, and melt away. The desire of the wicked will perish.'),
  ('120e6954-f2d0-58a5-a645-a73416b389dc', '58bc97b0-0cbb-52f8-abc8-95b88f6e9d7a', NULL, 1, 1, 'Praise Yah! Praise, you servants of Yahweh, praise the name of Yahweh.'),
  ('21a314e3-2bed-50e6-ab5b-c9d434afbe8b', '58bc97b0-0cbb-52f8-abc8-95b88f6e9d7a', NULL, 2, 2, 'Blessed be the name of Yahweh, from this time forth and forevermore.'),
  ('2ad266a6-dd1f-5556-a7ec-8baef56dfaf5', '58bc97b0-0cbb-52f8-abc8-95b88f6e9d7a', NULL, 3, 3, 'From the rising of the sun to the going down of the same, Yahweh''s name is to be praised.'),
  ('c3c3911f-9126-5ca6-a8c0-6f63945f06a1', '58bc97b0-0cbb-52f8-abc8-95b88f6e9d7a', NULL, 4, 4, 'Yahweh is high above all nations, his glory above the heavens.'),
  ('c5baf795-e0b5-5379-a1db-73047ea3160b', '58bc97b0-0cbb-52f8-abc8-95b88f6e9d7a', NULL, 5, 5, 'Who is like Yahweh, our God, who has his seat on high,'),
  ('2f7bdf12-d297-5c3f-a484-d1b286d4293f', '58bc97b0-0cbb-52f8-abc8-95b88f6e9d7a', NULL, 6, 6, 'Who stoops down to see in heaven and in the earth?'),
  ('40397424-17f0-5d8f-aaeb-8a86fc5afc69', '58bc97b0-0cbb-52f8-abc8-95b88f6e9d7a', NULL, 7, 7, 'He raises up the poor out of the dust. Lifts up the needy from the ash heap;'),
  ('b8022d0c-0b43-53f7-a37c-4a3fe4771348', '58bc97b0-0cbb-52f8-abc8-95b88f6e9d7a', NULL, 8, 8, 'that he may set him with princes, even with the princes of his people.'),
  ('7972fe22-5d40-5ce1-abd6-5b80e15a1b6e', '58bc97b0-0cbb-52f8-abc8-95b88f6e9d7a', NULL, 9, 9, 'He settles the barren woman in her home, as a joyful mother of children. Praise Yah!'),
  ('de3a40d9-26dc-515f-aabc-f148e4f59c73', '02f245df-eb4d-55b7-add1-d4f3570356e0', NULL, 1, 1, 'When Israel went forth out of Egypt, the house of Jacob from a people of foreign language;'),
  ('2423f245-0792-5c8d-a26e-a6e9539bb488', '02f245df-eb4d-55b7-add1-d4f3570356e0', NULL, 2, 2, 'Judah became his sanctuary, Israel his dominion.'),
  ('43275a81-8ce6-5148-ae68-9b5db793834f', '02f245df-eb4d-55b7-add1-d4f3570356e0', NULL, 3, 3, 'The sea saw it, and fled. The Jordan was driven back.'),
  ('0bff42c7-008f-5b20-acb8-9558bbf1ec99', '02f245df-eb4d-55b7-add1-d4f3570356e0', NULL, 4, 4, 'The mountains skipped like rams, the little hills like lambs.'),
  ('c13c37b1-0e49-55f6-a30f-4242a240000a', '02f245df-eb4d-55b7-add1-d4f3570356e0', NULL, 5, 5, 'What was it, you sea, that you fled? You Jordan, that you turned back?'),
  ('7772db31-542e-5808-ab10-8a6ac6e6f843', '02f245df-eb4d-55b7-add1-d4f3570356e0', NULL, 6, 6, 'You mountains, that you skipped like rams; you little hills, like lambs?'),
  ('91d59634-0768-5fec-a07b-eb6320fd7536', '02f245df-eb4d-55b7-add1-d4f3570356e0', NULL, 7, 7, 'Tremble, you earth, at the presence of the Lord, at the presence of the God of Jacob,'),
  ('d1d4945a-228d-54da-a933-a34ffe51ba78', '02f245df-eb4d-55b7-add1-d4f3570356e0', NULL, 8, 8, 'who turned the rock into a pool of water, the flint into a spring of waters.'),
  ('ea2450a2-61b3-55f2-ae15-f862d35af454', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 1, 1, 'Not to us, Yahweh, not to us, but to your name give glory, for your loving kindness, and for your truth''s sake.'),
  ('95484f08-019c-58cb-aea4-854c13dbaa2c', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 2, 2, 'Why should the nations say, "Where is their God, now?"'),
  ('ff01bbef-ade5-5570-a04d-060e7267fe5e', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 3, 3, 'But our God is in the heavens. He does whatever he pleases.'),
  ('79198c04-2960-5219-a901-ac0f65f93322', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 4, 4, 'Their idols are silver and gold, the work of men''s hands.'),
  ('a2ce041d-d089-5f97-a376-8d6aec5af246', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 5, 5, 'They have mouths, but they don''t speak. They have eyes, but they don''t see.'),
  ('5b5efed8-d2e5-5124-ab83-7498a0c33274', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 6, 6, 'They have ears, but they don''t hear. They have noses, but they don''t smell.'),
  ('373a28f1-dc20-5691-aefb-0acebc541dec', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 7, 7, 'They have hands, but they don''t feel. They have feet, but they don''t walk, neither do they speak through their throat.'),
  ('3bfa0a3e-2d11-518b-a841-57d3d9f8e0b8', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 8, 8, 'Those who make them will be like them; yes, everyone who trusts in them.'),
  ('4bcad11c-38c6-5986-a7cc-a42823f62901', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 9, 9, 'Israel, trust in Yahweh! He is their help and their shield.'),
  ('c17b334c-c2b0-52d8-a1d8-e8c994fc77cd', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 10, 10, 'House of Aaron, trust in Yahweh! He is their help and their shield.'),
  ('a4887368-6798-5f02-a490-24c49a97032b', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 11, 11, 'You who fear Yahweh, trust in Yahweh! He is their help and their shield.'),
  ('16136d5e-be48-5a1e-a1b5-a120cc2f4678', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 12, 12, 'Yahweh remembers us. He will bless us. He will bless the house of Israel. He will bless the house of Aaron.'),
  ('e5f6d7e0-8711-5913-a800-5bf10a0940b8', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 13, 13, 'He will bless those who fear Yahweh, both small and great.'),
  ('7bef0ab6-f362-5116-a210-6f1d94955c06', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 14, 14, 'May Yahweh increase you more and more, you and your children.'),
  ('3d01b4b8-7725-507f-ac2d-c92acd313fa1', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 15, 15, 'Blessed are you by Yahweh, who made heaven and earth.'),
  ('08d8e19b-1395-5cd4-a508-7873535403a9', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 16, 16, 'The heavens are the heavens of Yahweh; but the earth has he given to the children of men.'),
  ('358ea3e2-9622-593e-af94-6fc3e8ecaeca', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 17, 17, 'The dead don''t praise Yah, neither any who go down into silence;'),
  ('2a8da169-acae-5d6d-ab96-509b54af452c', '443beadb-b4e5-568d-a62a-3386c31050e2', NULL, 18, 18, 'But we will bless Yah, from this time forth and forevermore. Praise Yah!'),
  ('f3a47a76-d742-5f6c-a546-e9eada41308f', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 1, 1, 'I love Yahweh, because he listens to my voice, and my cries for mercy.'),
  ('d5ba709b-f9e5-5fb3-a8e5-d3715c3a8f5c', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 2, 2, 'Because he has turned his ear to me, therefore I will call on him as long as I live.'),
  ('db8da9f4-c036-5f37-ae8e-dafba8971bd3', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 3, 3, 'The cords of death surrounded me, the pains of Sheol got a hold of me. I found trouble and sorrow.'),
  ('6ccf3cbd-e8b1-51f2-abe4-332e4f8ad826', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 4, 4, 'Then I called on the name of Yahweh: "Yahweh, I beg you, deliver my soul."'),
  ('9ec36a58-37f2-537f-adb0-bfa3d3e84f43', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 5, 5, 'Yahweh is Gracious and righteous. Yes, our God is merciful.'),
  ('06194ef4-d118-50a9-ab81-d6d58e521069', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 6, 6, 'Yahweh preserves the simple. I was brought low, and he saved me.'),
  ('aa6620cc-bff5-5e3e-ad47-29c106d58ca3', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 7, 7, 'Return to your rest, my soul, for Yahweh has dealt bountifully with you.'),
  ('705c0c44-f41a-57b3-a294-de9fdb84d88f', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 8, 8, 'For you have delivered my soul from death, my eyes from tears, and my feet from falling.'),
  ('23ead64b-d56f-5643-a323-de67aa5757ec', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 9, 9, 'I will walk before Yahweh in the land of the living.'),
  ('76cec670-ca24-5a85-a230-299864fe2f2c', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 10, 10, 'I believed, therefore I said, "I was greatly afflicted."'),
  ('59133ed5-31cd-58a8-a65f-4b7eb22f0c62', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 11, 11, 'I said in my haste, "All men are liars."'),
  ('7f65c880-a4b3-5daa-a83b-770470368f70', '3c591df4-f2e0-5a75-a284-452643a2f7de', NULL, 12, 12, 'What will I give to Yahweh for all his benefits toward me?')
